const WAITING: readonly Episode[] = [
  {
    id: 'waiting.wait',
    weight: 3,
    cooldown: 0,
    plan: (s, c) => {
      play(s, c, 'wait', 2500, 4000)
      play(s, c, 'hold', 500, 1000)
    },
  },
  {
    id: 'waiting.peer',
    weight: 1.5,
    cooldown: 0,
    plan: (s, c) => {
      play(s, c, 'peer', 1500, 2500)
      play(s, c, 'wait', 2000, 3000)
    },
  },
  {
    id: 'waiting.ears',
    weight: 1,
    cooldown: 15_000,
    plan: (s, c) => {
      play(s, c, 'wait', 2000, 3000)
      play(s, c, 'earflick')
      play(s, c, 'look')
    },
  },
  {
    id: 'waiting.closer',
    weight: 0.6,
    cooldown: 60_000,
    walks: true,
    plan: (s, c) => {
      walkTo(s, c, nearby(s, c, 4, 8), 'stroll')
      play(s, c, 'peer', 1500, 2500)
      play(s, c, 'wait', 2000, 3000)
    },
  },
]

/** The episodes of each mood that has them; the others play one act at a time (program). */
export const EPISODES: Partial<Record<KitMood, readonly Episode[]>> = { idle: IDLE, wake: IDLE, think: THINK, work: WORK, search: SEARCH, test: TEST, waiting: WAITING }

/**
 * Picks the next episode by weight: none still cooling down, never the last one again, no walking
 * on a busy processor. Every set holds two episodes with no cooldown, so one is always free; were
 * none, the one begun longest ago (never the last) would play.
 */
function episode(s: KitState, p: KitProps, set: readonly Episode[]): void {
  const c = cursorOf(s)
  const isBusy = isSlow(p)
  const allowed = set.filter(e => !(isBusy && e.walks === true) && e.id !== s.lastEpisode)
  const fresh = allowed.filter(e => s.t - (s.cool[e.id] ?? -FOREVER) >= e.cooldown)
  const oldest = [...allowed].sort((a, b) => (s.cool[a.id] ?? -FOREVER) - (s.cool[b.id] ?? -FOREVER)).slice(0, 1)
  const pool = fresh.length > 0 ? fresh : oldest.length > 0 ? oldest : set.slice(0, 1)
  const weightOf = (e: Episode) => Math.max(0, typeof e.weight === 'function' ? e.weight(p) : e.weight)
  let r = rand(s) * pool.reduce((n, e) => n + weightOf(e), 0)
  let pick = pool[pool.length - 1]!
  for (const e of pool) {
    r -= weightOf(e)
    if (r <= 0) {
      pick = e
      break
    }
  }
  s.cool[pick.id] = s.t
  s.lastEpisode = pick.id
  pick.plan(s, c)
}

/** Fills the queue with what Kit does next in its settled mood. */
function program(s: KitState, p: KitProps): void {
  const set = EPISODES[s.mood]
  if (set !== undefined) return episode(s, p, set)
  const c = cursorOf(s)
  const isBusy = isSlow(p)
  const last = s.recent[0]
  switch (s.mood) {
    case 'celebrate':
      toPosture(s, c, 'sit')
      return push(s, c, act('happy', Math.round(between(s, 2500, 4000)), 'sit'))
    case 'worried':
      toPosture(s, c, 'sit')
      return push(s, c, last === 'sweat' && rand(s) < 0.5 ? act('facepalm', 1700, 'sit') : act('sweat', Math.round(between(s, 2000, 3000)), 'sit'))
    case 'handoff': {
      // Pick up the notes, face the way out, walk off to the right.
      toPosture(s, c, 'stand')
      push(s, c, act('pickup', 700, 'stand'))
      face(s, c, 1)
      return push(s, c, act('walk', 0, 'stand', { to: s.lane + 2, speed: PACE.exit, style: 'exit' }))
    }
    case 'sleepy':
      toPosture(s, c, 'sit')
      return push(s, c, last === 'nod' && rand(s) < 0.4 ? act('yawn', 1700, 'sit') : act('nod', Math.round(between(s, 3000, 4500)), 'sit'))
    case 'sleep':
      toPosture(s, c, 'down')
      return push(s, c, act('nap', Math.round(between(s, 8000, 14_000)), 'down'))
    case 'dim':
      toPosture(s, c, 'sit')
      return push(s, c, act('doze', Math.round(between(s, 4000, 7000)), 'sit'))
    case 'tend':
      toPosture(s, c, 'sit')
      faceOpen(s, c)
      return push(s, c, last === 'tend' && rand(s) < 0.35 ? act('poke', 1500, 'sit') : act('tend', Math.round(between(s, 3000, 5000)), 'sit'))
    case 'tired': {
      if (!isBusy && last !== 'walk' && rand(s) < 0.15) {
        const span = maxX(s)
        walkTo(s, c, c.x + (c.x < span / 2 ? 1 : -1) * between(s, 2, 4), 'trudge')
      }
      toPosture(s, c, 'sit')
      if (last !== 'fan') faceOpen(s, c)
      return push(s, c, last === 'fan' ? act('hold', Math.round(between(s, 2000, 3000)), 'sit') : act('fan', Math.round(between(s, 2500, 3500)), 'sit'))
    }
  }
}

// ---------------------------------------------------------------------------
// Touch

/** Where on Kit a touch lands. */
export type Part = 'head' | 'nose' | 'tail' | 'body'

const FACING_YOU: ReadonlySet<Body> = new Set<Body>(['front', 'frontStand', 'back'])

/**
 * The part of Kit at `x` (lane units) and `y` (half units above the ground; null where the surface
 * cannot tell): its head (the top of it), its nose (the front of its face), its tail, or the rest of
 * it, its body. Null off Kit. Desktop's drawing stands a little taller than the terminal's.
 */
export function partAt(s: KitState, pose: Pose, x: number, y: number | null, surface: KitProps['surface']): Part | null {
  const u = x - (s.x + pose.dx)
  if (u < -1 || u > KIT_W + 1) return null
  const top = TOP[pose.body] * (surface === 'desktop' ? 1.2 : 1)
  // Unknown height: the middle of it (a nose at the front, its body in the middle, the tail behind).
  // How high on Kit, as a share of its ear tips (never `h`: in a .tsx file that is JSX's own name).
  const height = y === null ? 0.5 : (y - pose.dy) / top
  if (FACING_YOU.has(pose.body)) {
    if (u > 15.5) return 'tail'
    if (u >= 7.5 && u <= 12.5 && height >= 0.3 && height < 0.7) return 'nose'
    return height >= 0.55 ? 'head' : 'body'
  }
  // From its back to its front: the tail behind, the face at the front.
  const along = pose.facing === 1 ? u : KIT_W - u
  if (along < 5) return 'tail'
  if (along >= 14.5 && height >= 0.3 && height < 0.8) return 'nose'
  return height >= 0.55 ? 'head' : 'body'
}

/**
 * A touch at `x` (lane units) and `y` (half units above the ground, or null): on Kit, a reaction by
 * where it lands (a head pat, a nose boop, a tail flick, a pet on its body), a startle if it is
 * asleep, a glance up while Claude works; three touches in a few seconds are a giggle, five make it
 * dizzy, and then it needs a moment. Elsewhere in the lane while it idles: it looks there.
 */
export function touchKit(prev: KitState, p: KitProps, x: number, y: number | null = null): KitState {
  if (isCalm(p) || prev.isGone) return prev
  const s = copy(prev)
  const part = partAt(s, poseOf(s, p), x, y, p.surface)
  if (part === null) {
    if (s.mood === 'idle' && !isSlow(p) && s.t - s.reactedAt >= COOLDOWN_MS) notice(s, x)
    return s
  }
  // Dizzy: it needs a moment before anything more.
  if (s.t - s.dizzyAt < DIZZY_REST_MS) return s
  if (NAPS.has(s.act.kind) || (s.posture === 'down' && (s.mood === 'sleep' || s.mood === 'dim'))) {
    if (s.t - s.reactedAt >= COOLDOWN_MS) react(s, 'startled')
    s.taps = []
    return s
  }
  s.taps = [...s.taps.filter(t => s.t - t < TAP_WINDOW_MS), s.t]
  if (s.taps.length >= DIZZY_TAPS) {
    s.taps = []
    s.dizzyAt = s.t
    react(s, 'dizzy')
    return s
  }
  if (s.taps.length === GIGGLE_TAPS && !p.isWorking) {
    react(s, 'giggle')
    return s
  }
  if (s.t - s.reactedAt < COOLDOWN_MS) return s
  if (p.isWorking) react(s, 'glance')
  // A head pat again while it still leans into the last one: a purr.
  else if (part === 'head') react(s, s.lastReaction === 'pat' && s.t - s.reactedAt < PAT_CHAIN_MS ? 'purr' : 'pat')
  else if (part === 'nose') react(s, 'boop')
  else if (part === 'tail') react(s, 'swish')
  else react(s, nextReaction(s))
  return s
}

/** The next pet on its body from a shuffled round of them: every one before any repeats, never twice running. */
function nextReaction(s: KitState): ActKind {
  if (s.bag.length === 0) {
    const bag = [...REACTIONS]
    for (let i = bag.length - 1; i > 0; i--) {
      const j = Math.floor(rand(s) * (i + 1))
      ;[bag[i], bag[j]] = [bag[j]!, bag[i]!]
    }
    if (bag[0] === s.lastReaction) bag.push(bag.shift()!)
    s.bag = bag
  }
  return s.bag.shift() ?? 'purr'
}

const REACTION_MS: Partial<Record<ActKind, number>> = { purr: 1800, hop: 750, spin: 1600, blush: 1500, earflick: 800, boop: 900, roll: 2200, highfive: 1100, startled: 1300, glance: 900, dizzy: 2200, pat: 1600, giggle: 1300, swish: 1400 }

function react(s: KitState, kind: ActKind): void {
  interrupt(s)
  const c = cursorOf(s)
  const dur = REACTION_MS[kind] ?? 1000
  if (kind === 'roll') {
    toPosture(s, c, 'down')
    push(s, c, act('roll', dur, 'down'))
    toPosture(s, c, 'sit')
  } else if (kind === 'purr') {
    toPosture(s, c, 'sit')
    push(s, c, act('purr', dur, 'sit'))
  } else if (kind === 'startled') {
    push(s, c, act('startled', dur, c.posture))
  } else {
    if (c.posture === 'down') toPosture(s, c, 'sit')
    push(s, c, act(kind, dur, c.posture))
  }
  s.reactedAt = s.t
  s.lastReaction = kind
}

function notice(s: KitState, x: number): void {
  interrupt(s)
  const c = cursorOf(s)
  const center = c.x + KIT_W / 2
  if (c.posture === 'down') toPosture(s, c, 'sit')
  face(s, c, x - center)
  push(s, c, act('notice', 900, c.posture))
  if (rand(s) < 0.5) {
    walkTo(s, c, x - KIT_W / 2 - Math.sign(x - center) * 4, 'stroll')
    toPosture(s, c, 'sit')
  }
  s.reactedAt = s.t
}

// ---------------------------------------------------------------------------
// Poses: what is drawn, the same words for both surfaces

export type Body = 'stand' | 'walkA' | 'walkB' | 'sit' | 'crouch' | 'hop' | 'ball' | 'lie' | 'stretch' | 'roll' | 'front' | 'frontStand' | 'back'
export type Eyes = 'open' | 'blink' | 'closed' | 'happy' | 'wide' | 'up' | 'down' | 'back' | 'focus' | 'half' | 'dizzy' | 'squint'
export type Mouth = 'none' | 'smile' | 'open' | 'yawn' | 'gasp' | 'wavy' | 'blep' | 'cat'
export type Ears = 'up' | 'back' | 'flick' | 'perk' | 'droop'
export type Arms =
  | 'rest'
  | 'wave'
  | 'cheer'
  | 'typeA'
  | 'typeB'
  | 'face'
  | 'scratchA'
  | 'scratchB'
  | 'groom'
  | 'hold'
  | 'poke'
  | 'fanA'
  | 'fanB'
  | 'reach'
  | 'chin'
  | 'warm'
export type Prop = 'keyboard' | 'book' | 'bookFlip' | 'glasses' | 'magnifier' | 'notes' | 'fireA' | 'fireB' | 'fireC' | 'stick' | 'flag' | 'fan' | 'leaf'

export type Pose = {
  body: Body
  facing: 1 | -1
  eyes: Eyes
  mouth: Mouth
  ears: Ears
  /** The tail's swing, -1 (low) to 1 (high). */
  tail: number
  arms: Arms
  blush: boolean
  props: Prop[]
  /** Lifted off the ground (half units), and nudged along (units: a wiggle). */
  dy: number
  dx: number
  /** A breath in: Desktop draws the body a pixel fuller. */
  breath: boolean
}

export type ParticleKind = 'heart' | 'spark' | 'confetti' | 'z' | 'bigZ' | 'bang' | 'question' | 'dots' | 'note' | 'sweat' | 'star' | 'butterfly' | 'leaf' | 'bubble' | 'spinner' | 'ember'

/** Something drawn beside Kit: where (lane units across, half units up), which frame, which color. */
export type Particle = { kind: ParticleKind; x: number; y: number; frame: number; tone: number }

export type Drawable = { x: number; pose: Pose; particles: Particle[]; isGone: boolean; isDim: boolean; caption: string }

/** How high Kit's ear tips are above the ground, in half units, by body. */
const TOP: Record<Body, number> = { stand: 9, walkA: 9, walkB: 9, hop: 9, frontStand: 9, sit: 8, front: 8, back: 8, crouch: 7, ball: 5, lie: 6, stretch: 7, roll: 6 }
const SIDE: ReadonlySet<Body> = new Set<Body>(['stand', 'walkA', 'walkB', 'sit', 'crouch', 'hop', 'ball', 'lie', 'stretch', 'roll'])

const bodyOf = (posture: Posture): Body => (posture === 'stand' ? 'stand' : posture === 'sit' ? 'sit' : 'ball')
const beat = (e: number, ms: number): number => Math.floor(e / ms)
const alt = (e: number, ms: number): boolean => beat(e, ms) % 2 === 0
const isBlink = (t: number, v: number): boolean => (t + (v % 997)) % (3100 + (v % 5) * 260) < 150
const swing = (t: number, period: number): number => Math.sin((t / period) * Math.PI * 2)

function basePose(s: KitState): Pose {
  return {
    body: bodyOf(s.posture),
    facing: s.facing,
    eyes: isBlink(s.t, s.act.v) ? 'blink' : 'open',
    mouth: 'none',
    ears: 'up',
    tail: swing(s.t, 2600) * 0.6,
    arms: 'rest',
    blush: false,
    props: [],
    dy: 0,
    dx: 0,
    breath: swing(s.t, 2400) > 0.55,
  }
}

/** The front-facing body for the posture Kit is in. */
const frontOf = (posture: Posture): Body => (posture === 'stand' ? 'frontStand' : 'front')

/** The pose Kit is in, from the act and how far into it Kit is. */
export function poseOf(s: KitState, p: KitProps): Pose {
  const a = s.act
  const e = s.t - a.t0
  const o = basePose(s)
  const v = a.v
  switch (a.kind) {
    case 'hold': {
      // Now and then a glance: back over its shoulder, up, or at you.
      const look = v % 6
      const mid = e > 900 && e < 1900
      if (mid && look === 0) o.eyes = 'back'
      else if (mid && look === 1) o.eyes = 'up'
      else if (mid && look === 2 && s.posture !== 'down') o.body = frontOf(s.posture)
      if (s.mood === 'tired') o.eyes = 'half'
      if (s.mood === 'celebrate') {
        o.eyes = 'happy'
        o.mouth = 'smile'
      }
      if (s.mood === 'worried') o.mouth = 'wavy'
      if (s.posture === 'down') o.eyes = 'closed'
      return o
    }
    case 'walk': {
      if (a.style === 'stop') return o
      const stepMs = a.style === 'sprint' ? 110 : a.style === 'stroll' || a.style === 'enter' || a.style === 'exit' || a.style === 'carry' ? 220 : 320
      o.body = alt(e, stepMs) ? 'walkA' : 'walkB'
      o.tail = swing(s.t, a.style === 'sprint' ? 400 : 900) * 0.8
      if (a.style === 'sprint') {
        o.ears = 'back'
        o.eyes = 'focus'
        if (alt(e, 220)) o.dy = 1
      } else if (a.style === 'carry') {
        o.props = ['notes']
        o.arms = 'hold'
      } else if (a.style === 'magnify') {
        o.props = ['magnifier']
        o.arms = 'hold'
        o.eyes = 'down'
      } else if (a.style === 'exit') {
        o.props = ['notes']
        o.mouth = 'smile'
      } else if (a.style === 'trudge') {
        o.eyes = 'half'
        o.mouth = 'wavy'
      } else if (a.style === 'pace') o.eyes = isBlink(s.t, v) ? 'blink' : 'up'
      return o
    }
    case 'turn':
      o.body = s.posture === 'down' ? 'ball' : frontOf(s.posture)
      o.eyes = s.posture === 'down' ? 'closed' : 'open'
      return o
    case 'sitDown':
    case 'standUp':
      o.body = 'crouch'
      return o
    case 'lieDown':
    case 'getUp':
      o.body = 'lie'
      o.eyes = 'half'
      return o
    case 'gone':
      return o
    case 'stretch':
      if (e < 250 || e > 1450) o.body = 'crouch'
      else {
        o.body = 'stretch'
        o.eyes = 'closed'
        o.mouth = e > 500 && e < 1100 ? 'yawn' : 'cat'
        o.tail = 1
      }
      return o
    case 'yawn':
      if (e > 200 && e < 1300) {
        o.eyes = 'closed'
        o.mouth = 'yawn'
        o.ears = 'back'
      } else if (e >= 1300) o.eyes = 'half'
      return o
    case 'scratch':
      o.arms = alt(e, 160) ? 'scratchA' : 'scratchB'
      o.eyes = 'squint'
      o.ears = alt(e, 320) ? 'flick' : 'up'
      return o
    case 'groom':
      o.arms = beat(e, 380) % 3 === 2 ? 'rest' : 'groom'
      o.eyes = 'closed'
      o.mouth = alt(e, 380) ? 'blep' : 'none'
      return o
    case 'swish':
      o.eyes = e < 1800 ? 'back' : 'open'
      o.tail = swing(e, 700)
      return o
    case 'look':
      o.eyes = e < 800 ? 'up' : e < 1700 ? 'back' : isBlink(s.t, v) ? 'blink' : 'open'
      o.ears = e < 800 ? 'perk' : 'up'
      return o
    case 'watch':
      o.eyes = isBlink(s.t, v) ? 'blink' : 'down'
      return o
    case 'butterfly': {
      o.eyes = 'up'
      o.ears = 'perk'
      if ((e > 1500 && e < 1900) || (e > 2300 && e < 2700)) o.arms = 'reach'
      if (e > 2800 && e < 3300) {
        o.body = 'hop'
        o.dy = Math.round(2 * Math.sin(((e - 2800) / 500) * Math.PI))
        o.arms = 'reach'
      }
      if (e > 3500) o.mouth = 'smile'
      return o
    }
    case 'pounce':
      if (e < 900) {
        o.body = 'crouch'
        o.eyes = 'focus'
        o.ears = 'perk'
        o.tail = swing(e, 300)
      } else if (e < 1400) {
        o.body = 'hop'
        o.dy = Math.round(2 * Math.sin(((e - 900) / 500) * Math.PI))
        o.eyes = 'wide'
        o.arms = 'reach'
      } else if (e < 1600) o.body = 'crouch'
      else {
        o.eyes = 'happy'
        o.mouth = 'smile'
        o.props = ['leaf']
      }
      return o
    case 'sneeze':
      if (e < 500) {
        o.eyes = 'squint'
        o.mouth = 'open'
      } else if (e < 800) {
        o.eyes = 'closed'
        o.mouth = 'open'
        o.ears = 'back'
        o.dy = 1
      } else o.eyes = 'blink'
      return o
    case 'nod':
      o.eyes = beat(e, 900) % 3 === 2 ? 'closed' : 'half'
      o.ears = 'droop'
      return o
    case 'ponder':
      o.eyes = isBlink(s.t, v) ? 'blink' : 'up'
      if (a.posture === 'sit') o.arms = 'chin'
      return o
    case 'type': {
      const burst = beat(e, 1500) % 4 !== 3
      o.props = ['keyboard']
      o.arms = burst ? (alt(e, 140) ? 'typeA' : 'typeB') : 'typeA'
      o.eyes = burst ? 'down' : isBlink(s.t, v) ? 'blink' : 'focus'
      return o
    }
    case 'check':
      o.props = ['keyboard']
      o.eyes = e < 900 ? 'up' : 'blink'
      o.ears = 'perk'
      return o
    case 'read':
      o.props = beat(e, 1700) % 4 === 3 && e % 1700 < 250 ? ['bookFlip', 'glasses'] : ['book', 'glasses']
      o.arms = 'hold'
      o.eyes = isBlink(s.t, v) ? 'blink' : 'down'
      return o
    case 'magnify':
      o.props = ['magnifier']
      o.arms = 'hold'
      o.eyes = e < 1000 ? 'down' : 'wide'
      return o
    case 'watchTest':
      o.eyes = e % 2400 > 1700 ? 'back' : isBlink(s.t, v) ? 'blink' : 'up'
      o.tail = swing(s.t, 520)
      o.ears = 'perk'
      return o
    case 'dance': {
      // Beats: a hop, a landing, a turn to you and round, arms up, and once more.
      const b = beat(e, 200)
      const steps: Body[] = ['crouch', 'hop', 'stand', 'frontStand', 'stand', 'frontStand', 'stand', 'crouch', 'hop', 'stand', 'frontStand', 'stand', 'hop']
      o.body = steps[b % steps.length] ?? 'stand'
      // Round once on the fifth beat: you, the other way, you again.
      if (b % steps.length === 4) o.facing = s.facing === 1 ? -1 : 1
      if (o.body === 'hop') o.dy = 2
      o.arms = o.body === 'hop' || o.body === 'frontStand' ? 'cheer' : 'rest'
      o.eyes = 'happy'
      o.mouth = 'open'
      o.tail = swing(e, 400)
      return o
    }
    case 'happy':
      o.eyes = 'happy'
      o.mouth = 'smile'
      o.tail = swing(s.t, 1100)
      if (e % 1800 > 1500) o.dy = 1
      return o
    case 'startle':
      o.eyes = 'wide'
      o.mouth = 'gasp'
      o.ears = 'up'
      if (e < 220) o.dy = 1
      if (s.posture === 'down') o.body = 'ball'
      return o
    case 'facepalm':
      o.body = frontOf(s.posture === 'down' ? 'sit' : s.posture)
      o.arms = 'face'
      o.eyes = 'closed'
      o.ears = 'back'
      o.mouth = 'wavy'
      return o
    case 'sweat':
      o.eyes = alt(e, 700) ? 'wide' : 'half'
      o.mouth = 'wavy'
      o.ears = 'back'
      return o
    case 'wait':
      o.body = 'front'
      o.eyes = isBlink(s.t, v) ? 'blink' : 'open'
      o.ears = e % 2600 > 2300 ? 'flick' : 'up'
      o.blush = true
      return o
    case 'pickup':
      if (e < 250) o.body = 'crouch'
      else if (e < 500) {
        o.body = 'hop'
        o.dy = 1
      }
      if (e >= 250) o.props = ['notes']
      o.mouth = 'smile'
      return o
    case 'nap':
      o.body = 'ball'
      o.eyes = 'closed'
      o.ears = e % 5000 > 4700 ? 'flick' : 'up'
      o.tail = 0
      return o
    case 'doze':
      o.eyes = 'closed'
      o.ears = 'droop'
      return o
    case 'tend':
    case 'poke': {
      const flame = beat(s.t, 170) % 3
      o.props = [flame === 0 ? 'fireA' : flame === 1 ? 'fireB' : 'fireC']
      if (a.kind === 'poke') {
        o.props.push('stick')
        o.arms = alt(e, 250) ? 'poke' : 'hold'
        o.eyes = 'focus'
      } else {
        o.arms = 'warm'
        o.eyes = isBlink(s.t, v) ? 'blink' : 'happy'
      }
      return o
    }
    case 'fan':
      o.props = ['fan']
      o.arms = alt(e, 260) ? 'fanA' : 'fanB'
      o.eyes = 'half'
      o.mouth = 'wavy'
      return o
    case 'stamp':
      if (e < 300) o.body = 'crouch'
      else if (e < 650) {
        o.body = 'hop'
        o.dy = 2
        o.arms = 'cheer'
      } else {
        o.props = ['flag']
        o.eyes = 'happy'
        o.mouth = 'smile'
        o.arms = e < 1200 ? 'wave' : 'rest'
      }
      return o
    case 'greet':
      if (e < 1200) {
        o.body = e < 200 || e > 1000 ? 'crouch' : 'stretch'
        o.eyes = 'closed'
        o.mouth = e > 300 && e < 900 ? 'yawn' : 'none'
      } else {
        o.eyes = e < 1600 ? 'wide' : 'open'
        o.ears = 'perk'
      }
      return o
    case 'purr':
      o.eyes = 'happy'
      o.mouth = 'cat'
      o.blush = true
      o.tail = swing(s.t, 800)
      return o
    case 'hop':
      if (e < 150 || (e > 520 && e < 680)) o.body = 'crouch'
      else if (e <= 520) {
        o.body = 'hop'
        o.dy = Math.round(3 * Math.sin(((e - 150) / 370) * Math.PI))
      }
      o.eyes = 'happy'
      o.mouth = 'smile'
      return o
    case 'spin': {
      // Round twice: the side it faces, you, the far side, its back; at the end you again, then as it was.
      const b = beat(e, 200)
      const k = b % 4
      const isStanding = s.posture === 'stand'
      if (b >= 7 || k === 1) o.body = frontOf(s.posture)
      else if (k === 2) {
        o.facing = s.facing === 1 ? -1 : 1
        o.body = isStanding ? 'stand' : 'sit'
      } else if (k === 3) o.body = isStanding ? 'frontStand' : 'back'
      o.eyes = 'happy'
      o.dy = b < 7 ? 1 : 0
      return o
    }
    case 'blush':
      o.body = frontOf(s.posture)
      o.blush = true
      o.eyes = 'happy'
      o.mouth = 'smile'
      o.dx = e < 1100 && alt(e, 130) ? 0.5 : 0
      return o
    case 'earflick':
      o.ears = alt(e, 150) ? 'flick' : 'up'
      o.eyes = e < 300 ? 'blink' : 'open'
      return o
    case 'boop':
      o.body = frontOf(s.posture)
      o.eyes = e < 450 ? 'squint' : 'happy'
      o.mouth = e < 450 ? 'none' : 'smile'
      o.ears = e < 450 ? 'back' : 'up'
      return o
    case 'roll':
      o.body = 'roll'
      o.eyes = 'happy'
      o.mouth = 'smile'
      o.tail = swing(e, 500)
      o.dx = alt(e, 260) ? 0 : 0.5
      return o
    case 'highfive':
      o.body = frontOf(s.posture)
      o.arms = e > 150 ? 'wave' : 'rest'
      o.eyes = e > 450 ? 'happy' : 'open'
      o.mouth = 'smile'
      return o
    case 'startled':
      if (s.posture === 'down') {
        o.body = 'ball'
        o.eyes = e < 700 ? 'wide' : 'half'
        o.dy = e < 200 ? 1 : 0
      } else {
        o.eyes = e < 700 ? 'wide' : 'half'
        o.mouth = e < 700 ? 'gasp' : 'wavy'
        o.dy = e < 220 ? 1 : 0
      }
      o.ears = e < 700 ? 'up' : 'droop'
      return o
    case 'glance':
      o.body = frontOf(s.posture === 'down' ? 'sit' : s.posture)
      if (s.posture === 'down') o.body = 'ball'
      o.eyes = 'open'
      o.ears = 'perk'
      return o
    case 'notice':
      o.eyes = 'open'
      o.ears = 'perk'
      return o
    case 'dizzy':
      o.eyes = 'dizzy'
      o.mouth = 'wavy'
      o.ears = 'droop'
      o.dx = beat(e, 200) % 2 === 0 ? 0 : 0.5
      if (s.posture === 'down') o.body = 'ball'
      return o
    case 'review':
      // A look at the notes (a clipboard), now and then up from them.
      o.props = ['notes']
      o.arms = 'hold'
      o.eyes = e % 2600 > 2100 ? 'up' : isBlink(s.t, v) ? 'blink' : 'down'
      return o
    case 'peer':
      // Looking down toward the prompt.
      o.body = frontOf(s.posture === 'down' ? 'sit' : s.posture)
      o.eyes = isBlink(s.t, v) ? 'blink' : 'down'
      o.ears = 'perk'
      return o
    case 'arrive':
      // Switched on: an ear flick and a little bounce, so it reads as alive at once.
      o.ears = alt(e, 150) ? 'flick' : 'perk'
      o.eyes = e < 250 ? 'blink' : 'open'
      o.dy = e > 150 && e < 400 ? 1 : 0
      return o
    case 'pat':
      // Leans into a pat on the head: eyes shut happily, ears flat, a purr, the tail going.
      o.eyes = e < 900 ? 'closed' : 'happy'
      o.ears = 'back'
      o.mouth = 'cat'
      o.blush = true
      o.tail = swing(e, 350)
      o.dx = e < 900 && alt(e, 180) ? 0.5 : 0
      return o
    case 'giggle': {
      // Many touches: a happy twirl.
      const b = beat(e, 160)
      const k = b % 4
      if (k === 1) o.body = frontOf(s.posture)
      else if (k === 2) o.facing = s.facing === 1 ? -1 : 1
      else if (k === 3) o.body = s.posture === 'stand' ? 'frontStand' : 'back'
      o.eyes = 'happy'
      o.mouth = 'open'
      o.dy = b % 2 === 0 ? 1 : 0
      return o
    }
  }
}

/** Where Kit's head is, for what floats beside it: the body's middle, its ear tips, its front. */
function anchorOf(s: KitState, pose: Pose): { cx: number; head: number; top: number; front: number } {
  const cx = s.x + pose.dx + KIT_W / 2
  const isSide = SIDE.has(pose.body)
  return { cx, head: cx + (isSide ? pose.facing * 2.5 : 0), top: TOP[pose.body] + pose.dy, front: cx + (isSide ? pose.facing * 8 : 7) }
}

/** What floats beside Kit in this act: hearts, sparks, confetti, Zzz, a question mark... */
export function particlesOf(s: KitState, p: KitProps, pose: Pose): Particle[] {
  const a = s.act
  const e = s.t - a.t0
  const at = anchorOf(s, pose)
  const f = pose.facing
  const out: Particle[] = []
  const add = (kind: ParticleKind, x: number, y: number, frame = 0, tone = 0) => out.push({ kind, x, y, frame, tone })
  const rising = (kind: ParticleKind, spawn: number, life: number, i: number, dx: number, height: number) => {
    const age = e - spawn
    if (age < 0 || age > life) return
    const u = age / life
    add(kind, at.head + f * dx + Math.sin(u * 3 + i) * 0.8, at.top + 1 + u * height, i, i)
  }
  switch (a.kind) {
    case 'hold':
      if (s.mood === 'tired' && e % 2200 < 900) add('sweat', at.head + f * 5, at.top - 1 - (e % 2200) / 450)
      break
    case 'walk':
      if (a.style === 'trudge' && e % 2000 < 800) add('sweat', at.head + f * 5, at.top - 1 - (e % 2000) / 400)
      break
    case 'ponder':
      add('dots', at.head + f * 2, at.top + 2, (beat(e, 420) % 3) + 1)
      break
    case 'type':
      if (e % 1500 < 220) add('spark', at.front + f * 1.5, 4.5)
      break
    case 'watchTest':
      add('spinner', at.head + f * 6.5, at.top + 0.5, beat(s.t, 110) % 8)
      break
    case 'dance':
      if (e > 150)
        for (let i = 0; i < 14; i++) {
          const life = 1800 + ((a.v >> (i % 16)) % 5) * 120
          const age = e - 150 - (i % 4) * 90
          if (age < 0 || age > life) continue
          const u = age / life
          const x0 = at.cx + (i - 6.5) * 1.5 + ((a.v >> i) % 3) - 1
          add('confetti', x0 + Math.sin(u * 6 + i) * 1.2, 15 - u * 13 - (i % 3), i % 3, i % 6)
        }
      break
    case 'happy':
      if (e % 2600 < 1200) rising('note', 0, 1200, 0, 3, 4)
      break
    case 'startle':
      if (e < 650) add('bang', at.head + f * 1, at.top + 2.5)
      break
    case 'facepalm':
      add('sweat', at.head - f * 5, at.top - 1 - (e % 1200) / 500)
      break
    case 'sweat':
      add('sweat', at.head + f * 5, at.top - 1 - (e % 1100) / 450)
      if (e % 1600 > 800) add('sweat', at.head - f * 5, at.top - 2 - (e % 800) / 400)
      break
    case 'wait':
      add('question', at.cx + 0.5, at.top + 2.5 + (alt(e, 600) ? 0 : 0.5))
      break
    case 'nap':
      for (let k = 0; k < 3; k++) {
        const u = ((e + k * 1300) % 3900) / 3900
        add(u > 0.5 ? 'bigZ' : 'z', at.head + f * (2 + u * 5) + Math.sin(u * 6) * 0.6, at.top + 1 + u * 7)
      }
      if (a.v % 3 === 0 && e > 3000 && e < 7500) add('bubble', at.head - f * 3, at.top + 3.5, beat(e - 3000, 450) > 1 ? 2 : beat(e - 3000, 450))
      break
    case 'doze':
    case 'nod':
      if (e % 3200 < 2000) add('z', at.head + f * 3 + ((e % 3200) / 2000) * 1.5 * f, at.top + 1 + ((e % 3200) / 2000) * 3)
      break
    case 'tend':
      for (let k = 0; k < 2; k++) {
        const u = ((e + k * 650) % 1300) / 1300
        add('ember', at.front + f * (2.5 + Math.sin(u * 5 + k)), 4 + u * 6, 0, k)
      }
      break
    case 'poke':
      if (e > 250 && e < 950) for (let k = 0; k < 4; k++) add('spark', at.front + f * (2 + (k - 1.5) * ((e - 250) / 350)), 5 + ((e - 250) / 700) * 4 + (k % 2), 0, k)
      break
    case 'fan':
      if (e % 2400 < 900) add('sweat', at.head - f * 5, at.top - 1 - (e % 2400) / 450)
      break
    case 'stamp':
      if (e > 650 && e < 1100) add('spark', at.cx + f * 13, 12, 0, 0)
      break
    case 'greet':
      if (e > 1200 && e < 1900) add('bang', at.head + f * 1, at.top + 2.5)
      break
    case 'purr':
      for (let k = 0; k < 3; k++) rising('heart', k * 450, 1200, k, 2 + k, 5)
      break
    case 'blush':
      rising('heart', 200, 1100, 0, 0, 4)
      break
    case 'boop':
      if (e < 400) add('spark', at.head + f * 5, at.top - 3)
      break
    case 'roll':
      for (let k = 0; k < 2; k++) rising('heart', 300 + k * 700, 1100, k, k * 2 - 1, 5)
      break
    case 'highfive':
      if (e > 300 && e < 650) add('spark', at.cx + 8.5, at.top + 1.5)
      break
    case 'startled':
      if (e < 750) add('bang', at.head + f * 1, at.top + 2.5)
      break
    case 'glance':
      if (e < 650) add('bang', at.head + f * 1.5, at.top + 2)
      break
    case 'notice':
      if (e < 700) add('question', at.head + f * 2, at.top + 2)
      break
    case 'dizzy':
      for (let k = 0; k < 3; k++) {
        const angle = e / 260 + (k * Math.PI * 2) / 3
        add('star', at.head + Math.cos(angle) * 4, at.top + 0.5 + Math.sin(angle) * 1.2, beat(e, 200) % 2, k)
      }
      break
    case 'butterfly': {
      if (e > 3800) break
      const away = e > 3200 ? (e - 3200) / 600 : 0
      const bx = at.cx + f * (5 + 3 * Math.sin(e / 500)) + f * away * 8
      const by = 12 + 1.5 * Math.cos(e / 330) + away * 4
      add('butterfly', bx, by, alt(e, 170) ? 0 : 1, 0)
      break
    }
    case 'pounce':
      if (e < 950) add('leaf', at.front + f * 2.5, 13 - (e / 950) * 10, alt(e, 240) ? 0 : 1)
      break
    case 'sneeze':
      if (e > 500 && e < 800) add('spark', at.head + f * 6, at.top - 4)
      break
    case 'pat':
      if (e < 450) add('spark', at.head, at.top + 1.5, 0, 1)
      for (let k = 0; k < 3; k++) rising('heart', 250 + k * 380, 1100, k, k - 1, 5)
      break
    case 'giggle':
      for (let k = 0; k < 4; k++) rising(k % 2 === 0 ? 'heart' : 'note', k * 300, 1000, k, (k - 1.5) * 2, 6)
      break
    case 'arrive':
      if (e < 500) add('spark', at.head + f * 2, at.top + 2)
      break
    default:
      break
  }
  return out
}

/** One still pose for a mood (Reduce motion, a strained machine), and the one mark that says it. */
export function stillOf(mood: KitMood, facing: 1 | -1): { pose: Pose; mark: ParticleKind | null } {
  const o: Pose = { body: 'sit', facing, eyes: 'open', mouth: 'none', ears: 'up', tail: 0, arms: 'rest', blush: false, props: [], dy: 0, dx: 0, breath: false }
  let mark: ParticleKind | null = null
  switch (mood) {
    case 'think':
      o.body = 'stand'
      o.eyes = 'up'
      mark = 'dots'
      break
    case 'work':
      o.props = ['keyboard']
      o.arms = 'typeA'
      o.eyes = 'down'
      break
    case 'search':
      o.props = ['book', 'glasses']
      o.arms = 'hold'
      o.eyes = 'down'
      break
    case 'test':
      o.eyes = 'up'
      mark = 'spinner'
      break
    case 'celebrate':
      o.eyes = 'happy'
      o.mouth = 'smile'
      break
    case 'worried':
      o.eyes = 'wide'
      o.mouth = 'wavy'
      mark = 'bang'
      break
    case 'waiting':
      o.body = 'front'
      o.blush = true
      mark = 'question'
      break
    case 'handoff':
      o.body = 'stand'
      o.props = ['notes']
      break
    case 'sleepy':
      o.eyes = 'half'
      o.ears = 'droop'
      break
    case 'sleep':
      o.body = 'ball'
      o.eyes = 'closed'
      mark = 'z'
      break
    case 'dim':
      o.eyes = 'closed'
      o.ears = 'droop'
      break
    case 'tend':
      o.props = ['fireA']
      o.arms = 'warm'
      break
    case 'tired':
      o.eyes = 'half'
      o.mouth = 'wavy'
      break
    default:
      break
  }
  return { pose: o, mark }
}

/** What to draw now: Kit's place, its pose, what floats beside it. */
export function drawableOf(s: KitState, p: KitProps): Drawable {
  if (isCalm(p)) {
    const still = stillOf(s.mood, s.facing)
    const at = anchorOf(s, still.pose)
    const particles: Particle[] =
      still.mark === null ? [] : [{ kind: still.mark, x: still.mark === 'spinner' ? at.head + s.facing * 6.5 : at.head + s.facing, y: still.mark === 'spinner' ? at.top + 0.5 : at.top + 2.5, frame: still.mark === 'dots' ? 3 : 0, tone: 0 }]
    return { x: s.x, pose: still.pose, particles, isGone: false, isDim: s.mood === 'dim', caption: p.caption }
  }
  const pose = poseOf(s, p)
  return { x: s.x, pose, particles: s.isGone ? [] : particlesOf(s, p, pose), isGone: s.isGone, isDim: s.mood === 'dim', caption: p.caption }
}

