  magnifier: { rows: ['....ggg..', '...gbbwg.', '..gbbbbwg', '..gbbbbbg', '..gBbbbbg', '...gBbbg.', '..c.ggg..', '.c.......', 'C........'], at: g => [g.body.cx + 10.2, g.body.cy - 6.6] },
