  fireB: { rows: ['....y...', '...ry...', '..ryyr..', '.rryyrr.', '.Ryyyrr.', '..ryyR..', 'CccCcccC', '.CC..CC.'], at: g => [g.body.cx + 11.4, 16] },
  fireC: { rows: ['........', '...yr...', '..ryyr..', '..ryyr..', '.rryyyr.', '..RyyR..', 'CccCcccC', '.CC..CC.'], at: g => [g.body.cx + 11.4, 16] },
