/**
 * Activity and change tracking for Focus View: every tool call as one
 * compact record, per-turn and per-session counters, what is running now,
 * and the files Claude changed with their hunks (from the tools' own
 * structured results: Edit/Write `structuredPatch`, Bash `bashEditDiff`).
 *
 * Presentation data only: nothing here changes what Claude reads.
 */

import { LIMITS } from '../constants'
import { plural } from '../core/format'
import { clean, shortPath } from '../core/text'
import { type HeavyKind, heavyKinds, heavyLabel } from './resources/heavy'
import { type ValidationKind, type ValidationRun, type ValidationStatus, validationKindOf } from './validation'

export type ActivityKind = 'read' | 'search' | 'edit' | 'shell' | 'web' | 'agent' | 'task' | 'mcp' | 'other'

export type ActivityItem = {
  id: string
  tool: string
  kind: ActivityKind
  /** Compact label: the command, the file, the query. */
  label: string
  /** `denied`: refused by a rule, a policy or the person; `held`: the Resource Governor kept it back. */
  status: 'running' | 'ok' | 'error' | 'denied' | 'held'
  /** Why it failed or was refused: the first line of the tool's answer. */
  reason: string | null
  /** The check a shell command runs (tests, build, ...), or null. */
  validation: ValidationKind | null
  /** A shell command interrupted before it finished (by the person or a timeout). */
  isInterrupted: boolean
  startedAt: number
  endedAt: number | null
  agentId: string | null
  turn: number
  heavy: HeavyKind[]
  /** Background task id when a shell command was sent to the background. */
  backgroundTaskId: string | null
}

export type FileChange = {
  path: string
  added: number
  removed: number
  /** False when no tool reported the lines (a file a shell command created, a diff the engine skipped). */
  hasDiff: boolean
  edits: number
  isCreated: boolean
  isDeleted: boolean
  lastAt: number
  firstTurn: number
  lastTurn: number
  /** Unified-diff hunks (most recent last), capped for display. */
  hunks: string
}

export type TurnStats = { index: number; startedAt: number | null; endedAt: number | null; tools: number; errors: number; files: Set<string> }

type Hunk = { oldStart: number; oldLines: number; newStart: number; newLines: number; lines: string[] }

const KIND_OF: Record<string, ActivityKind> = {
  Read: 'read',
  Glob: 'search',
  Grep: 'search',
  LS: 'search',
  Edit: 'edit',
  Write: 'edit',
  NotebookEdit: 'edit',
  MultiEdit: 'edit',
  Bash: 'shell',
  PowerShell: 'shell',
  WebFetch: 'web',
  WebSearch: 'web',
  Agent: 'agent',
  Task: 'agent',
  TaskCreate: 'task',
  TaskUpdate: 'task',
  TaskList: 'task',
  TaskGet: 'task',
  TaskStop: 'task',
  TodoWrite: 'task',
}

export const kindOf = (tool: string): ActivityKind =>
  KIND_OF[tool] ?? (tool.startsWith('mcp__') ? 'mcp' : 'other')

const str = (v: unknown): string => (typeof v === 'string' ? v : '')

/** One compact label for a tool call, safe to draw. */
export function labelOf(tool: string, input: Record<string, unknown>): string {
  switch (kindOf(tool)) {
    case 'shell':
      return clean(str(input.command).split('\n')[0], 120)
    case 'read':
    case 'edit':
      return shortPath(str(input.file_path) || str(input.notebook_path) || str(input.path), 64)
    case 'search':
      return clean(str(input.pattern) || str(input.path), 80)
    case 'web': {
      const url = str(input.url)
      if (url !== '') {
        try {
          return clean(new URL(url).host + new URL(url).pathname, 80)
        } catch {
          return clean(url, 80)
        }
      }
      return clean(str(input.query), 80)
    }
    case 'agent':
      return clean(str(input.description) || str(input.subagent_type) || 'subagent', 80)
    case 'task':
      return clean(str(input.subject) || str(input.task_id) || str(input.taskId) || tool, 80)
    case 'mcp': {
      const [, server, name] = tool.split('__')
      return clean(`${server ?? ''} · ${name ?? ''}`, 80)
    }
    default:
      return clean(str(input.skill) || str(input.description) || tool, 80)
  }
}

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

function hunksOf(v: unknown): Hunk[] {
  if (!Array.isArray(v)) return []
  return v.filter(
    (h): h is Hunk =>
      isRecord(h) && typeof h.oldStart === 'number' && typeof h.newStart === 'number' && Array.isArray(h.lines),
  )
}

function hunkText(hunks: readonly Hunk[]): string {
  return hunks
    // eslint-disable-next-line no-control-regex
    .map(h => `@@ -${h.oldStart},${h.oldLines} +${h.newStart},${h.newLines} @@\n${h.lines.map(l => l.replace(/[\u0000-\u0008\u000A-\u001F\u007F]/g, '').slice(0, 400)).join('\n')}`)
    .join('\n')
}

function countLines(hunks: readonly Hunk[]): { added: number; removed: number } {
  let added = 0
  let removed = 0
  for (const h of hunks) {
    for (const l of h.lines) {
      if (l.startsWith('+')) added += 1
      else if (l.startsWith('-')) removed += 1
    }
  }
  return { added, removed }
}

/** Keeps whole hunks from the end so the text stays a parseable unified diff. */
export function capHunks(text: string, max: number): string {
  if (text.length <= max) return text
  const parts = text.split(/\n(?=@@ )/)
  const kept: string[] = []
  let size = 0
  for (let i = parts.length - 1; i >= 0; i--) {
    const p = parts[i]!
    if (size + p.length + 1 > max) break
    kept.unshift(p)
    size += p.length + 1
  }
  return kept.join('\n')
}

/** Lines shown for a new file the diff left empty; its full count is kept apart. */
const NEW_FILE_LINES = 200

/** A file written whole: its content as one added hunk, since the engine's patch is empty for a create. */
function createdHunks(content: string): { hunks: Hunk[]; added: number } {
  const lines = content.replace(/\r\n/g, '\n').split('\n')
  if (lines.at(-1) === '') lines.pop()
  if (lines.length === 0) return { hunks: [], added: 0 }
  const shown = lines.slice(0, NEW_FILE_LINES)
  return { hunks: [{ oldStart: 0, oldLines: 0, newStart: 1, newLines: shown.length, lines: shown.map(l => `+${l}`) }], added: lines.length }
}

export type ReportedChange = { path: string; hunks: Hunk[]; isCreated: boolean; isDeleted: boolean; hasDiff: boolean; added?: number }

/** File changes a finished tool call reports in its structured result. */
export function changesOf(tool: string, result: unknown): ReportedChange[] {
  if (!isRecord(result)) return []
  if (tool === 'Edit' || tool === 'Write' || tool === 'MultiEdit') {
    if (result.staged === true) return []
    const path = str(result.filePath)
    if (path === '') return []
    const hunks = hunksOf(result.structuredPatch)
    const isCreated = result.type === 'create'
    if (isCreated && hunks.length === 0 && typeof result.content === 'string') {
      const created = createdHunks(result.content)
      return [{ path, hunks: created.hunks, isCreated, isDeleted: false, hasDiff: true, added: created.added }]
    }
    // An update without hunks changed nothing, or its diff was skipped: no lines to show either way.
    return [{ path, hunks, isCreated, isDeleted: false, hasDiff: hunks.length > 0 }]
  }
  if (tool === 'NotebookEdit') {
    const path = str(result.notebook_path) || str(result.notebookPath) || str(result.filePath)
    return path === '' ? [] : [{ path, hunks: [], isCreated: false, isDeleted: false, hasDiff: false }]
  }
  if (tool === 'Bash' || tool === 'PowerShell') {
    const diff = result.bashEditDiff
    if (!isRecord(diff) || !Array.isArray(diff.files)) return []
    const isUnavailable = diff.unavailable === true || diff.skipped === true
    return diff.files
      .filter(isRecord)
      .map(f => {
        const hunks = hunksOf(f.hunks)
        return { path: str(f.filePath), hunks, isCreated: f.created === true, isDeleted: f.deleted === true, hasDiff: !isUnavailable && hunks.length > 0 }
      })
      .filter(f => f.path !== '')
  }
  return []
}

/** Lines that never say why: a bare "Error:", an exit status, a runner echoing its script, a rule. */
const SAYS_NOTHING = [/^error:?$/i, /^exit code -?\d+$/i, /^> /, /^[=\-_*~#]{3,}/]

/** Lines that usually do: an error, a failure, a refusal. */
const SAYS_WHY = /\b(errors?|fail(ed|ure|ing)?|not ok|exception|cannot|can't|missing|denied|refused|not found|no such|expected|assert\w*)\b|[✖✗]/i

/**
 * Why a tool call failed or was refused, in one line of its answer: the first
 * line that names an error or a failure, else the first that says anything
 * ("Exit code 1" only when nothing else does).
 */
export function reasonOf(text: unknown): string | null {
  if (typeof text !== 'string') return null
  const lines = text
    .replace(/<\/?[a-z_-]+>/gi, ' ')
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l !== '')
  const telling = lines.filter(l => !SAYS_NOTHING.some(r => r.test(l)))
  const line = telling.find(l => SAYS_WHY.test(l)) ?? telling[0] ?? lines.find(l => !/^error:?$/i.test(l))
  return line === undefined ? null : clean(line, 140)
}

/** How a check ended: a command sent to the background has no outcome Control Room can see. */
export function validationStatusOf(i: ActivityItem): ValidationStatus {
  if (i.status === 'running') return 'running'
  if (i.status === 'denied' || i.status === 'held') return 'blocked'
  if (i.isInterrupted) return 'stopped'
  if (i.status === 'error') return 'failed'
  return i.backgroundTaskId !== null ? 'background' : 'passed'
}

export class ActivityTracker {
  items: ActivityItem[] = []
  private running = new Map<string, ActivityItem>()
  turn: TurnStats = { index: 0, startedAt: null, endedAt: null, tools: 0, errors: 0, files: new Set() }
  sessionTools = 0
  changes = new Map<string, FileChange>()
  /** Background shell tasks Claude started that have not been seen to end. */
  background = new Map<string, { id: string; label: string; since: number }>()

  turnStarted(now: number): void {
    this.turn = { index: this.turn.index + 1, startedAt: now, endedAt: null, tools: 0, errors: 0, files: new Set() }
  }

  /** The turn's numbers stay readable (Activity's "this turn") until the next one starts. */
  turnEnded(now: number = Date.now()): void {
    this.turn = { ...this.turn, endedAt: now }
    for (const [id, item] of this.running) {
      if (item.kind !== 'shell' || item.backgroundTaskId === null) this.running.delete(id)
    }
  }

  started(input: { id: string; tool: string; input: Record<string, unknown>; agentId: string | undefined; now: number }): ActivityItem {
    const command = kindOf(input.tool) === 'shell' ? str(input.input.command) : ''
    const item: ActivityItem = {
      id: input.id,
      tool: input.tool,
      kind: kindOf(input.tool),
      label: labelOf(input.tool, input.input),
      status: 'running',
      reason: null,
      validation: command === '' ? null : validationKindOf(command),
      isInterrupted: false,
      startedAt: input.now,
      endedAt: null,
      agentId: input.agentId ?? null,
      turn: this.turn.index,
      heavy: command === '' ? [] : heavyKinds(command),
      backgroundTaskId: null,
    }
    this.running.set(item.id, item)
    this.items.push(item)
    if (this.items.length > LIMITS.activityItems) this.items.splice(0, this.items.length - LIMITS.activityItems)
    this.turn.tools += 1
    this.sessionTools += 1
    return item
  }

  /**
   * A call refused before it ran: by the Permission Policy (`denied`) or held
   * back by the Resource Governor (`held`). Kept so Activity can say why.
   */
  refused(input: { id: string; tool: string; input: Record<string, unknown>; agentId: string | undefined; now: number; status: 'denied' | 'held'; reason: string }): ActivityItem {
    const item = this.started(input)
    this.running.delete(item.id)
    item.status = input.status
    item.reason = clean(input.reason, 140)
    item.endedAt = input.now
    return item
  }

  finished(input: { id: string; status: 'ok' | 'error' | 'denied'; result: unknown; text?: string; now: number }): FileChange[] {
    const item = this.running.get(input.id) ?? this.items.find(i => i.id === input.id)
    this.running.delete(input.id)
    if (!item) return []
    item.status = input.status
    item.endedAt = input.now
    if (input.status !== 'ok') item.reason = reasonOf(input.text)
    if (isRecord(input.result) && input.result.interrupted === true) item.isInterrupted = true
    if (input.status === 'error') this.turn.errors += 1
    if (isRecord(input.result) && typeof input.result.backgroundTaskId === 'string' && input.status === 'ok') {
      item.backgroundTaskId = input.result.backgroundTaskId
      this.background.set(item.backgroundTaskId, { id: item.backgroundTaskId, label: item.label, since: input.now })
    }
    if (input.status !== 'ok') return []
    const changed: FileChange[] = []
    for (const c of changesOf(item.tool, input.result)) {
      const prev = this.changes.get(c.path)
      const counts = countLines(c.hunks)
      const text = c.hunks.length > 0 ? hunkText(c.hunks) : ''
      const next: FileChange = {
        path: c.path,
        added: (prev?.added ?? 0) + (c.added ?? counts.added),
        removed: (prev?.removed ?? 0) + counts.removed,
        hasDiff: (prev?.hasDiff ?? false) || c.hasDiff,
        edits: (prev?.edits ?? 0) + 1,
        isCreated: (prev?.isCreated ?? false) || c.isCreated,
        isDeleted: c.isDeleted,
        lastAt: input.now,
        firstTurn: prev?.firstTurn ?? this.turn.index,
        lastTurn: this.turn.index,
        hunks: capHunks(text === '' ? (prev?.hunks ?? '') : prev?.hunks ? `${prev.hunks}\n${text}` : text, LIMITS.hunkChars),
      }
      this.changes.delete(c.path)
      this.changes.set(c.path, next)
      this.turn.files.add(c.path)
      changed.push(next)
    }
    while (this.changes.size > LIMITS.changedFiles) {
      const oldest = this.changes.keys().next().value
      if (oldest === undefined) break
      this.changes.delete(oldest)
    }
    return changed
  }

  /** A background task Claude stopped (TaskStop) or that reported its end. */
  backgroundEnded(taskId: string): void {
    this.background.delete(taskId)
  }

  /** Every check Claude ran in this context, oldest first. */
  validationRuns(): ValidationRun[] {
    const out: ValidationRun[] = []
    for (const i of this.items) {
      if (i.validation === null || i.agentId !== null) continue
      out.push({ kind: i.validation, command: i.label, status: validationStatusOf(i), startedAt: i.startedAt, endedAt: i.endedAt, turn: i.turn })
    }
    return out
  }

  runningItems(): ActivityItem[] {
    return [...this.running.values()]
  }

  /** Heavy jobs running now: foreground ones and Claude's background shells. */
  runningHeavy(): ActivityItem[] {
    const fg = this.runningItems().filter(i => i.heavy.length > 0 && i.status === 'running')
    const bg = this.items.filter(i => i.backgroundTaskId !== null && this.background.has(i.backgroundTaskId) && i.heavy.length > 0)
    return [...fg, ...bg.filter(b => !fg.includes(b))]
  }

  /** `Working · 27 tools · 6 files changed · tests running`. */
  summaryLine(input: { subagentsRunning: number }): string {
    const parts = ['Working', plural(this.turn.tools, 'tool')]
    if (this.turn.files.size > 0) parts.push(`${plural(this.turn.files.size, 'file')} changed`)
    if (this.turn.errors > 0) parts.push(plural(this.turn.errors, 'error'))
    const labels = new Set<string>()
    for (const item of this.runningItems()) for (const k of item.heavy) labels.add(heavyLabel(k))
    parts.push(...[...labels].slice(0, 2))
    if (input.subagentsRunning > 0) parts.push(`${plural(input.subagentsRunning, 'agent')} running`)
    return parts.join(' · ')
  }

  /** Everything the session changed, newest first. */
  changeList(): FileChange[] {
    return [...this.changes.values()].reverse()
  }

  totals(): { files: number; added: number; removed: number } {
    let added = 0
    let removed = 0
    for (const c of this.changes.values()) {
      added += c.added
      removed += c.removed
    }
    return { files: this.changes.size, added, removed }
  }

  /**
   * A fresh context (/clear): the activity list and counters start over.
   * Changed files are kept — they belong to the run, and a handoff should
   * not hide what the previous context changed.
   */
  reset(): void {
    this.items = []
    this.running.clear()
    this.turn = { index: 0, startedAt: null, endedAt: null, tools: 0, errors: 0, files: new Set() }
    this.sessionTools = 0
  }

  clearChanges(): void {
    this.changes.clear()
  }
}

files.hooks/features/background.ts:
/**
 * Background work as a handoff sees it: which of the tasks Claude Code reports in flight hold a
 * written handoff back, and which never should.
 *
 * A background process is not automatically a handoff blocker. Claude Code lists every task in
 * flight at each Stop (`background_tasks`: id, type, status, description, the shell command), and
 * those tasks belong to the session's process, not to the context: seen live on Claude Code 2.1.296,
 * a background shell started before `/clear` is still listed by the fresh context's Stop, and its
 * notification reaches the fresh context when it ends. So:
 *
 *   persistent   infrastructure that never ends by itself (a dev or preview server, a `--watch`,
 *                a tunnel, `tail -f`, a Monitor): never waited for. It keeps running across the
 *                clear, and the fresh context is told it is there.
 *   finite       work whose result may belong in the handoff (tests, builds, renders, a sleep):
 *                waited for, within the Handoff Supervisor's patience.
 *   agent        a background agent or a workflow: finite, its result comes back as a notification.
 *   unknown      a command nothing here recognises (`./run.sh`): waited for at first; the
 *                supervisor may ask a small isolated classifier, once, what it is.
 *
 * Pure: pattern matching over Claude Code's own words for the task, never a guess dressed as a fact.
 */

import { withoutQuoted } from './resources/heavy'
import { validationKindOf } from './validation'

export type TaskClass = 'persistent' | 'finite' | 'agent' | 'unknown'

/** Who decided a task's class: these rules, the isolated classifier, or the person. */
export type ClassBy = 'rule' | 'classifier' | 'person'

/** One task as Claude Code's Stop lists it (BackgroundTaskSummary), in the fields that matter here. */
export type TaskSummary = {
  id: string
  type: string
  description: string
  command?: string
  agentType?: string
  name?: string
}

export type TaskVerdict = { class: TaskClass; why: string; by: ClassBy }

/** Dev, preview and API servers, watchers, tunnels, followers: processes that never end by themselves. */
const PERSISTENT_COMMAND: readonly { re: RegExp; why: string }[] = [
  { re: /\b(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?[\w:.-]*(?:dev|serve|preview|watch|storybook)[\w:.-]*(?=\s|$|;|&|\|)/i, why: 'a dev, preview or watch script' },
  { re: /\b(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?start(?=\s|$|;|&|\|)/i, why: 'a start script (a server)' },
  { re: /\bvite\b(?!\s+(?:build|optimize)\b)/i, why: 'a Vite dev or preview server' },
  { re: /\b(?:next|nuxt|nuxi|astro|remix|gatsby)\s+(?:dev|start|preview|develop|serve)\b/i, why: 'a framework dev or preview server' },
  { re: /\b(?:ng\s+serve|vue-cli-service\s+serve|react-scripts\s+start|expo\s+start|storybook\s+dev|start-storybook|svelte-kit\s+dev|docusaurus\s+(?:start|serve)|mkdocs\s+serve|hugo\s+server|jekyll\s+serve|wrangler\s+dev|netlify\s+dev|vercel\s+dev)\b/i, why: 'a dev server' },
  { re: /\bwebpack(?:-dev-server|\s+serve)\b|\bparcel\b(?!\s+build\b)/i, why: 'a bundler dev server' },
  { re: /(?:^|[\s;&|(])(?:npx\s+(?:-y\s+|--yes\s+)?)?(?:http-server|live-server|serve)(?=\s|$)/i, why: 'a static file server' },
  { re: /\bpython[\d.]*\s+-m\s+(?:http\.server|SimpleHTTPServer)\b/i, why: 'a Python HTTP server' },
  { re: /\b(?:uvicorn|gunicorn|hypercorn|daphne|waitress-serve|flask\s+run|streamlit\s+run|panel\s+serve|bokeh\s+serve|mlflow\s+ui|tensorboard)\b|\bmanage\.py\s+runserver\b/i, why: 'a Python app server' },
  { re: /\bjupyter(?:-lab|-notebook)?\s+(?:lab|notebook|server)\b/i, why: 'a Jupyter server' },
  { re: /\brails\s+(?:s|server)\b|\b(?:puma|unicorn|thin\s+start)\b|\bphp\s+(?:-S\b|artisan\s+serve\b)|\bmix\s+phx\.server\b/i, why: 'an app server' },
  { re: /\b(?:nodemon|ts-node-dev|tsx\s+watch|cargo\s+watch|dotnet\s+watch|watchexec|entr|chokidar)\b|\b(?:node|bun|deno)\b[^;&|]*\s--watch\b|--watch(?:All)?\b|\btsc\b[^;&|]*\s-w\b/i, why: 'a watcher' },
  { re: /\bdocker(?:-compose|\s+compose)\s+up\b(?![^;&|]*\s(?:-d|--detach)\b)/i, why: 'containers attached to the shell' },
  { re: /\b(?:ngrok|cloudflared|localtunnel)\b|\bkubectl\s+(?:port-forward|proxy)\b|\bminikube\s+tunnel\b|\bssh\b[^;&|]*\s-[a-zA-Z]*N\b/i, why: 'a tunnel or port forward' },
  { re: /\b(?:redis-server|mongod|mysqld|memcached|ollama\s+serve|minio\s+server|pg_ctl\s+start)\b|\bpostgres\s+-D\b/i, why: 'a database or model server' },
  { re: /\btail\s+(?:-[a-zA-Z]*[fF]\b|--follow\b)|\b(?:journalctl|kubectl\s+logs|docker\s+(?:compose\s+)?logs)\b[^;&|]*\s-f\b|\bGet-Content\b[^;&|]*-Wait\b|\bwatch\s+-n\b/i, why: 'a log follower' },
  { re: /\bsleep\s+infinity\b|\bwhile\s+(?:true|:)\s*;?\s*do\b|\bfor\s*\(\s*;\s*;\s*\)/i, why: 'an endless loop' },
]

/** What Claude Code's description of a task says it is, when its command alone does not tell. */
const PERSISTENT_WORDS = /\b(?:dev|preview|local|api|web|http|static|file|app|mock|proxy)\s+server\b|\bserver\s+(?:on|at)\s+(?:port\s+)?:?\d{2,5}\b|\b(?:serve|serving|watch(?:er|ing)?|tunnel|port[- ]forward(?:ing)?|follow(?:ing)?\s+(?:the\s+)?logs?)\b/i

/** Work that ends by itself, recognised by its runner. */
const FINITE_COMMAND: readonly { re: RegExp; why: string }[] = [
  { re: /\bsleep\s+\d+(?:\.\d+)?[smhd]?\b/i, why: 'a timed wait' },
  { re: /\b(?:ffmpeg|remotion\s+render|blender\b[^;&|]*\s-b\b|magick|convert\s+\S+\.\w+)\b/i, why: 'a render' },
  { re: /\b(?:npm|pnpm|yarn|bun)\s+(?:i|install|ci|add)\b|\b(?:pip3?|uv|poetry|cargo|go)\s+(?:install|sync|fetch|get)\b/i, why: 'an install' },
  { re: /\b(?:curl|wget|scp|rsync)\b|\bgit\s+(?:clone|fetch|pull|push|gc)\b/i, why: 'a transfer' },
  { re: /\b(?:docker|podman)\s+(?:build|pull|push)\b/i, why: 'an image build or transfer' },
]

/** A check's runner names it finite (tests, builds, type-checks, linters, simulations). */
const finiteCheck = (command: string): string | null => {
  const kind = validationKindOf(command)
  return kind === null ? null : `a ${kind === 'typecheck' ? 'type-check' : kind === 'sim' ? 'simulation' : kind === 'check' ? 'project check' : kind === 'tests' ? 'test run' : kind}`
}

/**
 * A task's class from what Claude Code says of it. A watcher outranks the check it runs (`vitest
 * --watch`, `tsc -w` never end); a persistent command outranks a finite word in its description.
 */
export function classifyTask(t: TaskSummary): TaskVerdict {
  const type = t.type.toLowerCase()
  if (type === 'subagent' || type === 'agent' || type === 'teammate') return { class: 'agent', why: `a background agent${t.agentType === undefined ? '' : ` (${t.agentType})`}`, by: 'rule' }
  if (type === 'workflow') return { class: 'agent', why: `a workflow${t.name === undefined ? '' : ` (${t.name})`}`, by: 'rule' }
  // A Monitor watches a stream and reports events as they come: a watcher, not a result to wait for.
  if (type === 'monitor') return { class: 'persistent', why: 'a monitor (it reports events; it holds no result)', by: 'rule' }
  const command = withoutQuoted(t.command ?? '')
  const text = command.trim() === '' ? withoutQuoted(t.description) : command
  // A shell handed the real command as a quoted string (`bash -c "npm run dev"`) is read inside the quotes.
  const quoted = /^\s*(?:bash|sh|zsh|pwsh|powershell(?:\.exe)?|cmd(?:\.exe)?)\s+(?:-c|\/c|-Command)\s+(["'])([\s\S]*)\1\s*$/i.exec(t.command ?? '')
  const inner = quoted?.[2] ?? text
  for (const p of PERSISTENT_COMMAND) if (p.re.test(text) || p.re.test(inner)) return { class: 'persistent', why: p.why, by: 'rule' }
  const check = finiteCheck(text)
  if (check !== null) return { class: 'finite', why: check, by: 'rule' }
  for (const f of FINITE_COMMAND) if (f.re.test(text)) return { class: 'finite', why: f.why, by: 'rule' }
  // Claude Code's description is Claude's own words for the command ("Start the Vite preview server").
  if (t.description !== '' && t.description !== t.command && PERSISTENT_WORDS.test(t.description)) return { class: 'persistent', why: 'described as a server or watcher', by: 'rule' }
  return { class: 'unknown', why: type === 'shell' || type === '' ? 'a command these rules do not recognise' : `a ${t.type} task`, by: 'rule' }
}

/** Whether a task of this class holds a written handoff back: everything but infrastructure. */
export const isBlocking = (c: TaskClass): boolean => c !== 'persistent'

/** The words for a class, as the panel and the status bar say them. */
export const CLASS_WORDS: Record<TaskClass, string> = {
  persistent: 'Keeps running · not waited for',
  finite: 'Waited for · its result goes in the notes',
  agent: 'Waited for · an agent reports back',
  unknown: 'Waited for · not recognised',
}

/** The labels the isolated classifier picks from, and what each means as a class. */
export const CLASSIFIER_LABELS = ['persistent_service', 'finite_job', 'unclear'] as const

export function classifierText(t: TaskSummary): string {
  return [
    'Classify one background process an AI coding agent left running.',
    'persistent_service = it never exits by itself: a dev, preview or API server, a file watcher, a tunnel, a log follower, a REPL, a daemon.',
    'finite_job = it ends by itself with a result: a test run, a build, a render, a download, a script that finishes.',
    'unclear = the command does not say.',
    '',
    `COMMAND: ${(t.command ?? '').slice(0, 600)}`,
    `DESCRIPTION: ${t.description.slice(0, 300)}`,
  ].join('\n')
}

/** The classifier's label as a verdict; null when it could not tell. */
export function verdictOfLabel(label: string | undefined): TaskVerdict | null {
  if (label === 'persistent_service') return { class: 'persistent', why: 'a long-running service, by a small isolated classification', by: 'classifier' }
  if (label === 'finite_job') return { class: 'finite', why: 'a job that ends by itself, by a small isolated classification', by: 'classifier' }
  return null
}

files.hooks/features/intent.ts:
/**
 * Handoff-control intent: whether a short message the person typed while a handoff is under way is an
 * instruction about the handoff itself ("handoff now", "don't wait for the background process", "start
 * the fresh session now") rather than work for Claude. Read before the Cold Resume Guard, so such a
 * message never goes into the old context (a cold one least of all).
 *
 * Only short messages count: a sentence of work that happens to say "handoff" is a request, and goes
 * through the person's choice instead (app/runtime.ts handoffGuard). Pure pattern matching.
 */

export type HandoffIntent =
  /** Hand off now; background work keeps running for the fresh context. */
  | 'handoff-now'
  /** Do not wait for the background work (the same, said of the wait). */
  | 'skip-wait'
  /** Start the fresh context now (the notes checked first). */
  | 'fresh-now'
  /** Keep waiting for the background work. */
  | 'keep-waiting'
  /** Stop the background work, then hand off (asked to confirm first). */
  | 'stop-and-handoff'
  /** Call the handoff off: carry on in this context. */
  | 'cancel'

/** Longer than this, a message is work for Claude, not a control. */
const MAX_WORDS = 14

const LEAD = /^(?:(?:ok(?:ay)?|yes|yeah|sure|right|alright|fine|so|then|please|pls|just|now|hey|claude|sentinel|go ahead and|can you|could you|would you|i want you to|let'?s|lets)\s+)+/
const TAIL = /(?:\s+(?:please|pls|thanks|thank you|now|already|right away|immediately|asap|then|instead))+$/

const HANDOFF = String.raw`hand\s?-?off|handover|hand\s+over`
const WORK = String.raw`(?:the\s+|that\s+|this\s+|those\s+|these\s+|any\s+|all\s+)?(?:background\s+)?(?:process(?:es)?|servers?|tasks?|jobs?|work|build|render|tests?|test\s+run|script|it|them|vite|dev\s+server|preview(?:\s+server)?|watchers?)`

/** The message as compared: lower case, no punctuation or quotes, single spaces, politeness trimmed. */
export function normalizeIntent(text: string): string {
  return text
    .toLowerCase()
    .replace(/[’`]/g, "'")
    .replace(/[^a-z0-9'\s-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(LEAD, '')
    .replace(TAIL, '')
    .trim()
}

const RULES: readonly { intent: HandoffIntent; re: RegExp }[] = [
  // "stop the server and hand off", "kill the render then handoff"
  { intent: 'stop-and-handoff', re: new RegExp(String.raw`^(?:stop|kill|end|cancel|terminate)\s+${WORK}\s+(?:and|then|and then)\s+(?:${HANDOFF}|start\s+(?:the\s+)?fresh(?:\s+\w+)?)$`) },
  // "cancel the handoff", "don't hand off", "no handoff", "call off the handoff", "abort handoff"
  { intent: 'cancel', re: new RegExp(String.raw`^(?:(?:cancel|abort|stop|skip|forget|undo)\s+(?:the\s+|this\s+)?(?:${HANDOFF})|call\s+(?:the\s+)?(?:${HANDOFF})\s+off|call\s+off\s+(?:the\s+)?(?:${HANDOFF})|(?:don'?t|do\s+not|no)\s+(?:${HANDOFF})(?:\s+(?:yet|at\s+all))?|no\s+(?:${HANDOFF})(?:\s+yet)?|stay\s+(?:here|in\s+this\s+(?:context|session))|keep\s+(?:working\s+)?(?:here|in\s+this\s+(?:context|session)))$`) },
  // "keep waiting", "wait for it", "let it finish", "wait until the build finishes"
  { intent: 'keep-waiting', re: new RegExp(String.raw`^(?:(?:keep|continue|carry\s+on|go\s+on)\s+waiting(?:\s+for\s+${WORK})?|wait\s+for\s+${WORK}(?:\s+to\s+(?:finish|end|complete))?|wait\s+(?:until|till)\s+${WORK}\s+(?:finishes|ends|completes|is\s+done)|let\s+${WORK}\s+finish|wait\s+longer)$`) },
  // "don't wait for the background process", "skip the wait", "stop waiting", "ignore the server", "leave it running"
  { intent: 'skip-wait', re: new RegExp(String.raw`^(?:(?:don'?t|do\s+not|no\s+need\s+to|stop|quit)\s+wait(?:ing)?(?:\s+(?:for|on)\s+${WORK})?(?:\s+(?:and|just)\s+(?:${HANDOFF}|continue|go\s+on|proceed))?|skip\s+(?:the\s+)?wait(?:ing)?|(?:ignore|forget(?:\s+about)?)\s+${WORK}|leave\s+${WORK}\s+running(?:\s+and\s+(?:${HANDOFF}|continue|go\s+on|proceed))?|no\s+more\s+waiting)$`) },
  // "start the fresh session now", "fresh context", "clear the context", "new session"
  { intent: 'fresh-now', re: /^(?:(?:start|begin|open|go\s+to|switch\s+to|move\s+to|continue\s+in|use)\s+(?:a\s+|the\s+)?(?:fresh|new|clean)(?:\s+(?:session|context|chat|conversation|window))?|(?:fresh|new|clean)\s+(?:session|context|start)|start\s+fresh|clear\s+(?:the\s+)?(?:context|session|conversation)|(?:go|move)\s+fresh)$/ },
  // "handoff now", "hand off", "do the handoff", "proceed with the handoff", "finish the handoff"
  { intent: 'handoff-now', re: new RegExp(String.raw`^(?:(?:do|finish|complete|run|start|go\s+ahead\s+with|proceed\s+with|continue\s+with|go\s+on\s+with|force)\s+(?:the\s+|a\s+|your\s+)?(?:${HANDOFF})|(?:${HANDOFF})(?:\s+(?:to\s+(?:the\s+)?(?:fresh|new)\s+(?:session|context)))?)$`) },
]

/**
 * The handoff-control intent of a message, or null when it is not one (or too long to be one). A bare
 * "go ahead" or "continue" is never one: it answers whatever Claude asked last.
 */
export function handoffIntentOf(text: string): HandoffIntent | null {
  if (text.length > 200 || text.includes('\n')) return null
  const t = normalizeIntent(text)
  if (t === '' || t.split(' ').length > MAX_WORDS) return null
  for (const r of RULES) if (r.re.test(t)) return r.intent
  return null
}

/** The intent in words, for the trace and the drop reason. */
export const INTENT_WORDS: Record<HandoffIntent, string> = {
  'handoff-now': 'hand off now',
  'skip-wait': 'do not wait for the background work',
  'fresh-now': 'start the fresh context now',
  'keep-waiting': 'keep waiting',
  'stop-and-handoff': 'stop the background work, then hand off',
  cancel: 'call the handoff off',
}

files.hooks/features/supervisor.ts:
/**
 * The Handoff Supervisor: a watchdog over Context Autopilot's handoff.
 *
 * Every step of a handoff moves on an event (features/autopilot.ts), never a timer. The supervisor
 * does not move steps: it looks, deterministically and without a model call, at how long the
 * handoff has stood in its step and at the facts that explain it (the background work in flight
 * and what each task is, a question open to the person, the notes on disk, whether a turn runs),
 * and says what holds it: work worth waiting for, a server that never ends, a decision only the
 * person can make, a step whose event never came. The one thing it acts on by itself is the end
 * of a wait's patience (the machine's `waitExpired`): past it the handoff goes on and leaves the
 * work running for the fresh context, which Claude Code delivers its result to (seen live).
 *
 * Pure: the Runtime gathers the facts at its tick and acts on the diagnosis.
 */

import type { AutopilotState, BackgroundTask } from './autopilot'
import { blockingOf, classOf } from './autopilot'

export type SupervisorStatus = 'idle' | 'moving' | 'waiting' | 'stalled' | 'needs-you'

export type BlockerKind =
  /** Infrastructure (a server, a watcher): never holds a handoff, said so the person knows it keeps running. */
  | 'persistent'
  /** Finite work whose result may belong in the notes. */
  | 'finite'
  /** Finite work that outlasted the patience: the handoff goes on and leaves it running. */
  | 'long-finite'
  /** A task nothing recognises: waited for, and asked about once. */
  | 'unknown'
  /** Claude waits for the person's answer (a permission prompt, a question): the turn cannot end without it. */
  | 'decision-blocking'
  /** A choice that is the person's, that holds nothing up (Wait for me, an interrupted step). */
  | 'decision'
  /** A step whose turn never started or whose end was never seen. */
  | 'turn'
  /** The notes check, the clear or the compaction never finished. */
  | 'step'

export type SupervisorAction = 'handoff-now' | 'stop-and-handoff' | 'keep-waiting' | 'cancel' | 'start-fresh' | 'hand-off' | 'later'

export type Diagnosis = {
  status: SupervisorStatus
  /** The step, in words ("Waiting for background work"). */
  phase: string
  /** How long the handoff has stood in this step. */
  forMs: number
  blocker: { kind: BlockerKind; text: string } | null
  /** When the wait's patience ends (the handoff then goes on by itself), while it waits. */
  goesOnAt: number | null
  /** What the person can do now, most useful first. */
  actions: SupervisorAction[]
}

export type SupervisorInput = {
  now: number
  state: AutopilotState
  stateSince: number | null
  isTurnRunning: boolean
  /** The turn running is the handoff's own (its prompt, a retry). */
  isHandoffTurn: boolean
  background: readonly BackgroundTask[]
  waitSince: number | null
  waitUntil: number | null
  /** The person (or the patience) said not to wait: the handoff goes on when the turn running ends. */
  skipWait: boolean
  notesWritten: boolean | null
  /** Questions open to the person: Sentinel's Ask approvals, a running AskUserQuestion. */
  questionsOpen: number
  /**
   * How long the main conversation has shown no activity (no prompt, step, call or turn end); null when
   * not known. A turn whose start a reload hid still shows itself by its calls.
   */
  quietMs: number | null
  lastError: string | null
  continuation: 'clear' | 'compact' | 'manual'
}

/** How long each step may stand before the supervisor calls it stalled. */
export const STALL_MS = {
  requested: 2 * 60_000,
  verifying: 60_000,
  clearing: 60_000,
  resuming: 2 * 60_000,
  compacting: 11 * 60_000,
} as const

/**
 * How long the session must have been quiet (no prompt, step, call or turn end) before the supervisor
 * trusts that no turn runs unseen: a wait holding nothing is moved on, a handoff turn called stalled.
 */
export const QUIET_MS = 30_000

/** How long an unrecognised task is waited for before the isolated classifier is asked about it, once. */
export const CLASSIFY_AFTER_MS = 60_000

const PHASE: Record<AutopilotState, string> = {
  off: 'Off',
  armed: 'Watching the context',
  pending: 'Handoff due',
  requested: 'Starting the handoff',
  handoff: 'Claude is writing the notes',
  'waiting-background': 'Waiting for background work',
  verifying: 'Checking the notes',
  clearing: 'Starting the fresh context',
  compacting: 'Compacting the context',
  resuming: 'Resuming in the fresh context',
  awaiting: 'Waiting for you',
}

const names = (tasks: readonly BackgroundTask[]): string => {
  const shown = tasks.slice(0, 2).map(t => t.description)
  return `${shown.join('; ')}${tasks.length > 2 ? ` and ${tasks.length - 2} more` : ''}`
}

export function diagnose(i: SupervisorInput): Diagnosis {
  const forMs = i.stateSince === null ? 0 : Math.max(0, i.now - i.stateSince)
  const base = { phase: PHASE[i.state], forMs, goesOnAt: null as number | null }
  const result = (status: SupervisorStatus, blocker: Diagnosis['blocker'], actions: SupervisorAction[], goesOnAt: number | null = null): Diagnosis => ({ ...base, status, blocker, actions, goesOnAt })
  // A question to the person holds any turn, the handoff's included: only they can end it.
  if (i.isTurnRunning && i.questionsOpen > 0 && i.state !== 'off' && i.state !== 'armed') {
    return result('needs-you', { kind: 'decision-blocking', text: 'Claude is waiting for your answer before the turn can end' }, [])
  }
  switch (i.state) {
    case 'off':
    case 'armed':
      return result('idle', null, [])
    case 'pending':
      return i.isTurnRunning
        ? result('moving', null, ['hand-off'])
        : result('needs-you', { kind: 'decision', text: 'The step that reached the handoff point was interrupted: hand off when you are ready' }, ['hand-off', 'later'])
    case 'requested':
      return forMs >= STALL_MS.requested && !i.isTurnRunning
        ? result('stalled', { kind: 'turn', text: 'The handoff prompt has not started a turn' }, ['hand-off', 'cancel'])
        : result('moving', null, [])
    case 'handoff':
      // A turn running, or one a reload hid that still shows itself: Claude is writing the notes.
      if (i.isTurnRunning || i.quietMs === null || i.quietMs < QUIET_MS) return result('moving', null, ['handoff-now'])
      return result('stalled', { kind: 'turn', text: 'The handoff turn ended without Sentinel seeing it end' }, ['start-fresh', 'hand-off', 'cancel'])
    case 'waiting-background': {
      const blocking = blockingOf(i.background)
      const persistent = i.background.filter(t => classOf(t) === 'persistent')
      const keeps = persistent.length === 0 ? null : { kind: 'persistent' as const, text: `${names(persistent)} ${persistent.length === 1 ? 'keeps' : 'keep'} running and ${persistent.length === 1 ? 'is' : 'are'} not waited for` }
      if (blocking.length === 0) return result('moving', keeps, [])
      if (i.skipWait) return result('moving', { kind: 'turn', text: 'Not waiting for the background work: the handoff goes on when this turn ends' }, ['cancel'])
      const unknown = blocking.filter(t => classOf(t) === 'unknown')
      const isOver = i.waitUntil !== null && i.now >= i.waitUntil
      const kind: BlockerKind = isOver ? 'long-finite' : unknown.length === blocking.length ? 'unknown' : 'finite'
      const left = isOver ? ', past its wait: the handoff goes on and leaves it running' : ''
      const text = `${i.notesWritten === false ? 'Notes not written yet; ' : ''}waiting for ${names(blocking)}${left}`
      // Past the patience with no turn running the Runtime moves it on at once; a long wait is the person's to cut short.
      const status: SupervisorStatus = isOver ? 'stalled' : 'waiting'
      return result(status, { kind, text }, ['handoff-now', 'stop-and-handoff', 'keep-waiting', 'cancel'], i.waitUntil)
    }
    case 'verifying':
      return forMs >= STALL_MS.verifying ? result('stalled', { kind: 'step', text: 'The notes check has not finished' }, ['start-fresh', 'hand-off']) : result('moving', null, [])
    case 'clearing':
      if (i.isTurnRunning) return result('moving', { kind: 'turn', text: 'A turn you queued runs first; the context is cleared when it ends' }, [])
      return forMs >= STALL_MS.clearing ? result('stalled', { kind: 'step', text: 'The fresh context has not started' }, ['start-fresh']) : result('moving', null, [])
    case 'compacting':
      return forMs >= STALL_MS.compacting ? result('stalled', { kind: 'step', text: 'The compaction has not finished' }, ['start-fresh']) : result('moving', null, [])
    case 'resuming':
      return forMs >= STALL_MS.resuming && !i.isTurnRunning ? result('stalled', { kind: 'turn', text: 'The fresh context has not taken up the work' }, []) : result('moving', null, [])
    case 'awaiting':
      return result(
        'needs-you',
        {
          kind: 'decision',
          text: i.lastError === null ? (i.continuation === 'manual' ? 'The notes are written: start the fresh context when you are ready' : 'The handoff waits for you to start the fresh context') : `The handoff stopped: ${i.lastError}`,
        },
        ['start-fresh', 'later', 'cancel'],
      )
  }
}

/**
 * The one step the supervisor takes by itself, if any: a wait past its patience goes on (`waitExpired`;
 * under a running turn it goes on when that turn ends), and a wait that holds nothing any more, in a
 * quiet session, goes on (`unblocked`: no turn's end would come to move it). Never a judgement that a
 * turn ended: the turn's own end does that. Null when nothing is due.
 */
export function dueStep(i: Pick<SupervisorInput, 'now' | 'state' | 'isTurnRunning' | 'background' | 'waitUntil' | 'skipWait' | 'quietMs'>): 'waitExpired' | 'unblocked' | null {
  if (i.state !== 'waiting-background') return null
  const blocking = blockingOf(i.background)
  if (blocking.length > 0) return !i.skipWait && i.waitUntil !== null && i.now >= i.waitUntil ? 'waitExpired' : null
  if (i.isTurnRunning || i.quietMs === null || i.quietMs < QUIET_MS) return null
  return 'unblocked'
}

/** The tasks the isolated classifier should be asked about now: unrecognised, waited for at least a minute, not asked yet. */
export function toClassify(i: { now: number; waitSince: number | null; background: readonly BackgroundTask[]; asked: ReadonlySet<string> }): BackgroundTask[] {
  if (i.waitSince === null || i.now - i.waitSince < CLASSIFY_AFTER_MS) return []
  return i.background.filter(t => classOf(t) === 'unknown' && t.by !== 'classifier' && t.by !== 'person' && !i.asked.has(t.id))
}

/** One line for the debug trace: the diagnosis as it changed. */
export function traceLine(d: Diagnosis): string {
  const time = d.forMs >= 60_000 ? `${Math.round(d.forMs / 60_000)}m` : `${Math.round(d.forMs / 1000)}s`
  return `supervisor: ${d.phase} for ${time} · ${d.status}${d.blocker === null ? '' : ` · ${d.blocker.kind}: ${d.blocker.text}`}`
}

files.hooks/features/chain.ts:
/**
 * Session Chain: sequential contexts of one piece of work, kept as one run.
 *
 * A run starts with a fresh `claude` process (or continues when a session
 * that belongs to a stored run is resumed). Each /clear — the autopilot's or
 * the person's — ends the current session entry and opens the next one;
 * compactions are recorded as transitions inside a session (the session id
 * does not change). Pure data functions; persistence is the runtime's.
 */

import { LIMITS } from '../constants'
import type { HandoffRecord } from './handoff'
import type { EvidenceStore } from './evidence'
import { type RunOps, emptyOps } from './ops'
import { type Plan, emptyPlan } from './plan'
import type { RunQuest } from './quest'

export type SessionStart = 'startup' | 'resume' | 'clear' | 'handoff'

export type SessionEnd = 'handoff' | 'clear' | 'exit' | 'resume' | 'logout' | 'other'

export type Transition = {
  kind: 'compact' | 'auto-compact' | 'handoff-compact'
  at: number
  tokensBefore: number | null
  tokensAfter: number | null
}

export type SessionEntry = {
  id: string
  index: number
  startedAt: number
  endedAt: number | null
  start: SessionStart
  end: SessionEnd | null
  /** Highest context fill seen (tokens), the figure the chain shows. */
  peakTokens: number
  lastTokens: number
  window: number | null
  /** Cost as Claude Code reported it for this session; null when not exposed. */
  costUsd: number | null
  turns: number
  model: string | null
  /** Why the session ended, in words (e.g. "context reached 702k"). */
  endNote: string | null
  transitions: Transition[]
}

export type Run = {
  v: 1
  id: string
  number: number
  startedAt: number
  updatedAt: number
  root: string
  profile: string
  status: 'active' | 'ended'
  sessions: SessionEntry[]
  /** Claude's milestones for the run (its task list), carried across handoffs. Absent in runs before 1.0.2. */
  plan?: Plan
  /**
   * The run's objective: Claude's statement of it with its milestones when it gives one, else the
   * person's latest substantial request, in their words.
   */
  objective?: string | null
  /** Who stated the objective: Claude with its milestones, or the person's request. Absent before 1.3.0 (the person's). */
  objectiveBy?: 'claude' | 'person'
  /** Quest log: the run's XP and the milestones already paid for. Absent until it earns any. */
  quest?: RunQuest
  /** The latest handoff: its health when the notes were checked, and the fresh context's continuity. Absent before 1.2.0. */
  lastHandoff?: HandoffRecord | null
  /**
   * The run over time (features/ops.ts): the Mission Queue, the Decision Inbox, Watchers, the Run
   * Budget. Kept with the run, so it survives /clear, handoffs, reloads and a resumed session.
   * Absent before 1.6.0; read through `opsOf`, which validates it.
   */
  ops?: RunOps
  /**
   * Milestone evidence (features/evidence.ts): the files each milestone's work changed while under way,
   * and a snapshot of what each completed milestone stood on (its green checks, its files' blob ids),
   * compared with the workspace later. Absent before 1.7.0; read through `evidenceOf`.
   */
  evidence?: EvidenceStore
}

export function newSession(id: string, index: number, start: SessionStart, now: number): SessionEntry {
  return {
    id,
    index,
    startedAt: now,
    endedAt: null,
    start,
    end: null,
    peakTokens: 0,
    lastTokens: 0,
    window: null,
    costUsd: null,
    turns: 0,
    model: null,
    endNote: null,
    transitions: [],
  }
}

export function newRun(input: {
  id: string
  number: number
  sessionId: string
  root: string
  profile: string
  start: SessionStart
  now: number
}): Run {
  return {
    v: 1,
    id: input.id,
    number: input.number,
    startedAt: input.now,
    updatedAt: input.now,
    root: input.root,
    profile: input.profile,
    status: 'active',
    sessions: [newSession(input.sessionId, 1, input.start, input.now)],
    plan: emptyPlan(),
    objective: null,
    ops: emptyOps(),
  }
}

export const currentSession = (run: Run): SessionEntry | undefined => run.sessions.at(-1)

function withCurrent(run: Run, now: number, change: (s: SessionEntry) => SessionEntry): Run {
  const last = currentSession(run)
  if (!last) return run
  return { ...run, updatedAt: now, sessions: [...run.sessions.slice(0, -1), change(last)] }
}

/** Live figures after a turn (from `session.measure` / `$.session.usage()`). */
export function measure(
  run: Run,
  input: { tokens: number | undefined; window: number | undefined; costUsd: number | undefined; model?: string },
  now: number,
): Run {
  return withCurrent(run, now, s => ({
    ...s,
    lastTokens: input.tokens ?? s.lastTokens,
    peakTokens: Math.max(s.peakTokens, input.tokens ?? 0),
    window: input.window ?? s.window,
    costUsd: input.costUsd ?? s.costUsd,
    model: input.model ?? s.model,
  }))
}

export function countTurn(run: Run, now: number): Run {
  return withCurrent(run, now, s => ({ ...s, turns: s.turns + 1 }))
}

export function recordTransition(run: Run, transition: Transition): Run {
  return withCurrent(run, transition.at, s => ({ ...s, transitions: [...s.transitions, transition].slice(-20) }))
}

/** Ends the current session and opens the next one under `nextId`. */
export function rollOver(
  run: Run,
  input: { end: SessionEnd; endNote: string | null; nextId: string; nextStart: SessionStart; now: number },
): Run {
  const ended = withCurrent(run, input.now, s => ({ ...s, endedAt: input.now, end: input.end, endNote: input.endNote }))
  if (ended.sessions.some(s => s.id === input.nextId)) return ended
  const index = (currentSession(ended)?.index ?? 0) + 1
  const sessions = [...ended.sessions, newSession(input.nextId, index, input.nextStart, input.now)].slice(-LIMITS.sessionsPerRun)
  return { ...ended, sessions, status: 'active' }
}

export function endRun(run: Run, end: SessionEnd, now: number): Run {
  const ended = withCurrent(run, now, s => (s.endedAt === null ? { ...s, endedAt: now, end } : s))
  return { ...ended, status: 'ended' }
}

export type RunTotals = {
  sessions: number
  costUsd: number | null
  /** True when some session's cost was not exposed, so the total is partial. */
  isCostPartial: boolean
  turns: number
  peakTokens: number
  handoffs: number
  durationMs: number
}

export function totals(run: Run, now: number): RunTotals {
  let cost = 0
  let known = 0
  let turns = 0
  let peak = 0
  let handoffs = 0
  for (const s of run.sessions) {
    if (s.costUsd !== null) {
      cost += s.costUsd
      known += 1
    }
    turns += s.turns
    peak = Math.max(peak, s.peakTokens)
    if (s.end === 'handoff') handoffs += 1
  }
  const last = currentSession(run)
  const end = run.status === 'ended' ? (last?.endedAt ?? run.updatedAt) : now
  return {
    sessions: run.sessions.length,
    costUsd: known === 0 ? null : cost,
    isCostPartial: known > 0 && known < run.sessions.length,
    turns,
    peakTokens: peak,
    handoffs,
    durationMs: Math.max(0, end - run.startedAt),
  }
}

/** A short run id: time-ordered, unique enough for one machine's history. */
export function runIdOf(now: number, random: number): string {
  return `${now.toString(36)}-${Math.floor(random * 0xffffff).toString(36)}`
}

/** Keeps the newest ids, most recent first, without duplicates. */
export function updateIndex(index: readonly string[], id: string): { index: string[]; dropped: string[] } {
  const next = [id, ...index.filter(x => x !== id)]
  return { index: next.slice(0, LIMITS.runsKept), dropped: next.slice(LIMITS.runsKept) }
}

export function isRun(v: unknown): v is Run {
  if (typeof v !== 'object' || v === null) return false
  const r = v as Partial<Run>
  return r.v === 1 && typeof r.id === 'string' && typeof r.number === 'number' && Array.isArray(r.sessions)
}

files.hooks/features/evidence.ts:
/**
 * Milestone evidence: what a verified milestone stood on, and whether it still does.
 *
 * When a milestone is completed, Sentinel keeps a small snapshot of it: which milestone, when it was
 * verified and in which session, the checks that were green during its work (their kind and command),
 * the files its work changed (the edits Sentinel saw while it was under way, and the outputs Claude
 * named), each with Git's blob id of its content (`git hash-object --no-filters`: only the id is kept,
 * never the content), its size and modification time, and the commit HEAD pointed at. Nothing else is
 * hashed, never the repository.
 *
 * At a handoff, at a fresh context's start and (at most once a minute, only while snapshots exist) at
 * a turn's end, each snapshot is compared with the workspace. A file whose size and modification time
 * are unchanged is current without hashing; one that moved is hashed again, so a file only touched (or
 * changed and changed back) stays current. A change is never called wrong: the milestone's earlier
 * verification is *stale*, with which files changed, since when, and which checks to run again.
 *
 * Later milestones legitimately change the same files, so a change is weighed by who made it and
 * what verified it since:
 * - a change Sentinel saw (through Claude's tools) after which the latest run of every kind of check
 *   the milestone had passed: those checks cover the new content, so the snapshot takes it as its own
 *   (re-baselined, said quietly: "re-verified by Tests at 14:05", or by the later milestone); a change
 *   Sentinel did not see counts from when a comparison found it, as long as the file is still as found;
 * - a documentation file, or any file of a milestone verified with no check, changed by a later
 *   milestone that has since been completed: that milestone's verification owns it now (re-baselined);
 * - a change made while a later milestone is still under way, not yet covered: quiet ("being changed
 *   by M3"), not stale;
 * - anything else (a later milestone whose checks do not cover it, an edit with no milestone under way
 *   and no check after it, or a change outside Sentinel's view: the person, a checkout, a command whose
 *   changes Claude Code does not report) makes the evidence stale, until checks cover it as above or
 *   the person accepts the files as they are (`acceptChanges`: /cr evidence accept, or Accept in
 *   Activity), which re-baselines them as theirs.
 *
 * Only the milestone's own files are compared: a file its checks depend on but its work never changed
 * is not watched (that would mean hashing the repository).
 *
 * Pure: the Runtime gathers the stats and blob ids and keeps the store in the run record.
 */

import { clock } from '../core/format'

/** A file as found: whether it exists, its size and time (`stat`), its blob id (null: not hashed). */
export type Fingerprint = { exists: boolean; isDir?: boolean; size: number | null; mtimeMs: number | null; blob: string | null }

/** `isDoc`: documentation (README, docs, a changelog): verified by review, not by a check. */
export type EvidenceFile = Fingerprint & { path: string; isDoc?: boolean }

/** A check that was green during the milestone's work: its kind ("test"), name ("Tests"), command, when it ended. */
export type EvidenceCheck = { kind: string; label: string; command: string; at: number }

/** An edit Sentinel saw to a snapshot's file after it was verified: the milestone under way then (null: none), and when. */
export type Touch = { path: string; key: string | null; subject: string | null; at: number }

export type EvidenceStatus = 'current' | 'changing' | 'stale'

/** A file found changed since the snapshot (or since its re-baseline), and who changed it when Sentinel saw it. */
export type EvidenceChange = {
  path: string
  kind: 'changed' | 'deleted' | 'created'
  /** The later milestone whose work changed it; null: no milestone was under way, or the change was not seen. */
  by: string | null
  byKey: string | null
  /** That milestone is still under way. */
  isByActive: boolean
  /** Sentinel saw the edit (it came through Claude's tools); false: changed outside its view. */
  isSeen: boolean
  /** When Sentinel saw the edit; null for a change it did not see. */
  at: number | null
  /** When a comparison first found the file this way, and how it was then (a later change starts the clock again). */
  foundAt: number
  found: { size: number | null; mtimeMs: number | null; blob: string | null }
}

export type Snapshot = {
  key: string
  subject: string
  verifiedAt: number
  session: number
  checks: EvidenceCheck[]
  files: EvidenceFile[]
  /** The commit HEAD pointed at when verified; null outside a Git repository. */
  head: string | null
  touches: Touch[]
  /** Files whose evidence a later verified milestone took over, and which. */
  rebaselined: { path: string; by: string; at: number }[]
  status: EvidenceStatus
  changes: EvidenceChange[]
  /** When it was last compared with the workspace; null before the first comparison. */
  checkedAt: number | null
}

/** A milestone under way: when it was first seen under way, the files its work changed, the outputs Claude named. */
export type MilestoneWork = { since: number; files: { path: string; at: number }[]; outputs: string[] }

export type EvidenceStore = { work: Record<string, MilestoneWork>; snapshots: Snapshot[] }

export const emptyEvidence = (): EvidenceStore => ({ work: {}, snapshots: [] })

/** At most this many files per milestone (the latest edited), outputs Claude names, snapshots, and checks. */
export const EVIDENCE_LIMITS = { files: 12, outputs: 10, snapshots: 30, checks: 6, touches: 24, observed: 200 } as const

/** Larger files are not hashed: their size and time stand in for their content. */
export const HASH_MAX_BYTES = 8 * 1024 * 1024

/** Turn ends compare the workspace at most this often. */
export const EVIDENCE_CHECK_EVERY_MS = 60_000

const samePath = (a: string, b: string): boolean => a === b || a.replace(/\\/g, '/').toLowerCase() === b.replace(/\\/g, '/').toLowerCase()

function workOf(store: EvidenceStore, key: string, now: number): MilestoneWork {
  return store.work[key] ?? { since: now, files: [], outputs: [] }
}

/** At most as many milestones' work as snapshots: the ones begun longest ago go first (a plan rewritten without them). */
function trimmed(work: Record<string, MilestoneWork>): Record<string, MilestoneWork> {
  const keys = Object.keys(work)
  if (keys.length <= EVIDENCE_LIMITS.snapshots) return work
  const kept = keys.sort((a, b) => (work[b]?.since ?? 0) - (work[a]?.since ?? 0)).slice(0, EVIDENCE_LIMITS.snapshots)
  return Object.fromEntries(kept.map(k => [k, work[k]!]))
}

/** A milestone is under way (in progress or verifying): its work counts from the first time it is seen so. */
export function noteActive(store: EvidenceStore, key: string, now: number): EvidenceStore {
  if (store.work[key] !== undefined) return store
  return { ...store, work: trimmed({ ...store.work, [key]: workOf(store, key, now) }) }
}

/**
 * Files Claude's tools changed (edits, writes, a command's reported changes), with the milestone under
 * way: they become that milestone's files, and an edit to a verified milestone's file is noted on its
 * snapshot as a touch (who changed it, when).
 */
export function noteEdits(store: EvidenceStore, current: { key: string; subject: string } | null, paths: readonly string[], now: number): EvidenceStore {
  if (paths.length === 0) return store
  let work = store.work
  if (current !== null) {
    const w = workOf(store, current.key, now)
    const kept = w.files.filter(f => !paths.some(p => samePath(p, f.path)))
    const files = [...kept, ...paths.map(path => ({ path, at: now }))].slice(-EVIDENCE_LIMITS.files)
    work = trimmed({ ...work, [current.key]: { ...w, files } })
  }
  const snapshots = store.snapshots.map(s => {
    if (now < s.verifiedAt) return s
    const hit = paths.filter(p => s.files.some(f => samePath(f.path, p)))
    if (hit.length === 0) return s
    const touches = [...s.touches.filter(t => !hit.some(p => samePath(p, t.path))), ...hit.map(path => ({ path, key: current?.key ?? null, subject: current?.subject ?? null, at: now }))].slice(-EVIDENCE_LIMITS.touches)
    return { ...s, touches }
  })
  return { work, snapshots }
}

/** Outputs Claude named for a milestone (files its verification covers that no editing tool reported: generated, rendered). */
export function noteOutputs(store: EvidenceStore, key: string, outputs: readonly string[], now: number): EvidenceStore {
  const clean = outputs.map(o => o.trim()).filter(o => o !== '' && o.length <= 400)
  if (clean.length === 0) return store
  const w = workOf(store, key, now)
  const merged = [...w.outputs.filter(o => !clean.some(c => samePath(c, o))), ...clean].slice(-EVIDENCE_LIMITS.outputs)
  if (merged.length === w.outputs.length && merged.every((o, i) => o === w.outputs[i]) && store.work[key] !== undefined) return store
  return { ...store, work: { ...store.work, [key]: { ...w, outputs: merged } } }
}

/** The files a milestone's snapshot covers: the outputs Claude named, then the latest edited files. */
export function filesFor(store: EvidenceStore, key: string): string[] {
  const w = store.work[key]
  if (w === undefined) return []
  const out: string[] = []
  for (const p of [...w.outputs, ...[...w.files].reverse().map(f => f.path)]) {
    if (!out.some(o => samePath(o, p))) out.push(p)
    if (out.length >= EVIDENCE_LIMITS.files) break
  }
  return out
}

/** Where a milestone's work began: first seen under way, else the latest earlier verification, else `fallback`. */
export function windowStart(store: EvidenceStore, key: string, fallback: number): number {
  const w = store.work[key]
  if (w !== undefined) return w.since
  const earlier = store.snapshots.filter(s => s.key !== key).map(s => s.verifiedAt)
  return earlier.length === 0 ? fallback : Math.max(...earlier)
}

/** A check run as Activity's Validation records it. */
export type CheckRun = { kind: string; label: string; command: string; status: string; endedAt: number | null }

/** The checks green in a window: for each kind, its latest run that ended in the window, when that run passed. */
export function greenChecks(runs: readonly CheckRun[], from: number, to: number): EvidenceCheck[] {
  const latest = new Map<string, CheckRun>()
  for (const r of runs) {
    if (r.endedAt === null || r.endedAt < from || r.endedAt > to) continue
    const prev = latest.get(r.kind)
    if (prev === undefined || (prev.endedAt ?? 0) <= r.endedAt) latest.set(r.kind, r)
  }
  return [...latest.values()]
    .filter(r => r.status === 'passed')
    .map(r => ({ kind: r.kind, label: r.label, command: r.command.slice(0, 160), at: r.endedAt ?? to }))
    .slice(0, EVIDENCE_LIMITS.checks)
}

/**
 * Whether green checks cover every kind the earlier milestone had, each ending after the change (a check
 * that ended in the very millisecond of an edit cannot have run on it).
 */
export function covers(later: readonly EvidenceCheck[], earlier: readonly EvidenceCheck[], after: number): boolean {
  return earlier.every(e => later.some(l => l.kind === e.kind && l.at > after))
}

const statusOf = (changes: readonly EvidenceChange[]): EvidenceStatus => (changes.length === 0 ? 'current' : changes.every(c => c.isByActive) ? 'changing' : 'stale')

/**
 * A milestone verified: its snapshot, replacing one it had before (a milestone reopened and completed
 * again). Earlier snapshots it changed are re-baselined at the next comparison (`compare`).
 */
export function addSnapshot(store: EvidenceStore, snap: Omit<Snapshot, 'touches' | 'rebaselined' | 'status' | 'changes' | 'checkedAt'>): EvidenceStore {
  const { [snap.key]: _done, ...work } = store.work
  void _done
  const fresh: Snapshot = { ...snap, touches: [], rebaselined: [], status: 'current', changes: [], checkedAt: snap.verifiedAt }
  return { work, snapshots: [...store.snapshots.filter(s => s.key !== snap.key), fresh].slice(-EVIDENCE_LIMITS.snapshots) }
}

/**
 * A milestone no longer completed (reopened): its snapshot goes, and its files go back to its work, so
 * the snapshot taken when it is completed again still covers them.
 */
export function dropSnapshots(store: EvidenceStore, keys: readonly string[], now: number): EvidenceStore {
  const dropped = store.snapshots.filter(s => keys.includes(s.key))
  if (dropped.length === 0) return store
  const work = { ...store.work }
  for (const s of dropped) {
    const w = work[s.key] ?? { since: now, files: [], outputs: [] }
    const earlier = s.files.filter(f => !w.files.some(x => samePath(x.path, f.path))).map(f => ({ path: f.path, at: s.verifiedAt }))
    work[s.key] = { ...w, files: [...earlier, ...w.files].slice(-EVIDENCE_LIMITS.files) }
  }
  return { work, snapshots: store.snapshots.filter(s => !keys.includes(s.key)) }
}

/** Every file the snapshots cover, to look at (at most EVIDENCE_LIMITS.observed). */
export function pathsToObserve(store: EvidenceStore): string[] {
  const out: string[] = []
  for (const s of [...store.snapshots].reverse()) {
    for (const f of s.files) if (!out.some(o => samePath(o, f.path))) out.push(f.path)
  }
  return out.slice(0, EVIDENCE_LIMITS.observed)
}

/** The files whose size or time moved since a snapshot that holds their blob: those, and only those, are hashed again. */
export function pathsToHash(store: EvidenceStore, found: ReadonlyMap<string, Fingerprint>): string[] {
  const out: string[] = []
  for (const s of store.snapshots) {
    for (const f of s.files) {
      const o = found.get(f.path)
      if (o === undefined || !o.exists || o.isDir === true || f.blob === null) continue
      if (o.size !== null && o.size > HASH_MAX_BYTES) continue
      if (o.size === f.size && o.mtimeMs === f.mtimeMs) continue
      if (!out.some(p => samePath(p, f.path))) out.push(f.path)
    }
  }
  return out
}

/** How one file compares with its record: the same, changed in some way, or not decidable now (a hash that failed). */
function compareFile(f: EvidenceFile, o: Fingerprint): 'same' | 'changed' | 'deleted' | 'created' | 'unknown' {
  if (!f.exists && !o.exists) return 'same'
  if (f.exists && !o.exists) return 'deleted'
  if (!f.exists && o.exists) return 'created'
  if (f.isDir === true || o.isDir === true) return 'same'
  if (o.size === f.size && o.mtimeMs === f.mtimeMs) return 'same'
  if (f.blob !== null && o.blob !== null) return f.blob === o.blob ? 'same' : 'changed'
  if (f.blob !== null && o.blob === null) return o.size !== f.size ? 'changed' : 'unknown'
  return 'changed'
}

export type CompareContext = {
  /** Milestones under way now (in progress, verifying). */
  active: ReadonlySet<string>
  /** Milestones completed now. */
  completed: ReadonlySet<string>
  /** The latest run of each kind of check, when it passed (`greenChecks` over this context's runs). */
  green: readonly EvidenceCheck[]
  now: number
}

/** Who took a re-baselined file over, in words: the checks that passed after the change, or the later milestone. */
const checkWords = (checks: readonly EvidenceCheck[], kinds: readonly string[], now: number): string => {
  const used = checks.filter(c => kinds.includes(c.kind))
  const at = used.length === 0 ? now : Math.max(...used.map(c => c.at))
  return `${[...new Set(used.map(c => c.label))].join(', ')} at ${clock(at)}`
}

/** The file is still as a comparison found it before (same size and time, or the same content). */
const isStill = (was: EvidenceChange['found'], o: Fingerprint): boolean =>
  (was.size === o.size && was.mtimeMs === o.mtimeMs) || (was.blob !== null && was.blob === o.blob)

/**
 * The snapshots compared with the workspace as found (`found`, by path; blob ids for the files that
 * moved). A change covered since (see the module's comment) re-baselines the file on what was found.
 * The same store when nothing changed.
 */
export function compare(store: EvidenceStore, found: ReadonlyMap<string, Fingerprint>, ctx: CompareContext): EvidenceStore {
  let isChanged = false
  const snapshots = store.snapshots.map(s => {
    const changes: EvidenceChange[] = []
    let files = s.files
    let touches = s.touches
    let rebaselined = s.rebaselined
    const kinds = [...new Set(s.checks.map(c => c.kind))]
    for (const f of s.files) {
      const o = found.get(f.path)
      const before = s.changes.find(c => samePath(c.path, f.path))
      if (o === undefined) {
        // Not looked at this time: what was found before stands.
        if (before !== undefined) changes.push(before)
        continue
      }
      const verdict = compareFile(f, o)
      if (verdict === 'same') continue
      if (verdict === 'unknown') {
        if (before !== undefined) changes.push(before)
        continue
      }
      const t = touches.find(x => samePath(x.path, f.path))
      // An unseen change counts from when it was first found, while the file stays as it was found then.
      const foundAt = before !== undefined && before.kind === verdict && isStill(before.found, o) ? before.foundAt : ctx.now
      const since = t?.at ?? foundAt
      const isFoundBefore = t !== undefined || foundAt < ctx.now
      const byLater = t !== undefined && t.key !== null && t.key !== s.key && ctx.completed.has(t.key) ? t.subject : null
      const by =
        kinds.length > 0 && isFoundBefore && covers(ctx.green, s.checks, since)
          ? checkWords(ctx.green, kinds, ctx.now)
          : byLater !== null && (f.isDoc === true || kinds.length === 0)
            ? byLater
            : null
      if (by !== null) {
        files = files.map(x => (x === f ? { ...o, path: f.path, ...(f.isDoc === true ? { isDoc: true } : {}) } : x))
        touches = touches.filter(x => x !== t)
        rebaselined = [...rebaselined.filter(r => !samePath(r.path, f.path)), { path: f.path, by, at: ctx.now }].slice(-EVIDENCE_LIMITS.files)
        continue
      }
      changes.push({
        path: f.path,
        kind: verdict,
        by: t?.subject ?? null,
        byKey: t?.key ?? null,
        isByActive: t !== undefined && t.key !== null && ctx.active.has(t.key),
        isSeen: t !== undefined,
        at: t?.at ?? null,
        foundAt,
        found: { size: o.size, mtimeMs: o.mtimeMs, blob: o.blob },
      })
    }
    const status = statusOf(changes)
    const isSame = files === s.files && status === s.status && changes.length === s.changes.length && changes.every((c, i) => JSON.stringify(c) === JSON.stringify(s.changes[i]))
    if (isSame) return s.checkedAt === null ? { ...s, checkedAt: ctx.now } : s
    isChanged = true
    return { ...s, files, touches, rebaselined, changes, status, checkedAt: ctx.now }
  })
  return isChanged || snapshots.some((s, i) => s !== store.snapshots[i]) ? { ...store, snapshots } : store
}

/**
 * The person accepts the files of stale snapshots as they are now (`key`: one milestone; null: every
 * stale one): their evidence is re-baselined on what was found, "accepted by you". Files not found
 * this time keep their change.
 */
export function acceptChanges(store: EvidenceStore, key: string | null, found: ReadonlyMap<string, Fingerprint>, now: number): EvidenceStore {
  let isChanged = false
  const snapshots = store.snapshots.map(s => {
    if (s.status !== 'stale' || (key !== null && s.key !== key)) return s
    const taken = s.changes.filter(c => found.has(c.path))
    if (taken.length === 0) return s
    isChanged = true
    const files = s.files.map(f => {
      const o = found.get(f.path)
      return o === undefined || !taken.some(c => samePath(c.path, f.path)) ? f : { ...o, path: f.path, ...(f.isDoc === true ? { isDoc: true } : {}) }
    })
    const changes = s.changes.filter(c => !taken.includes(c))
    return {
      ...s,
      files,
      touches: s.touches.filter(t => !taken.some(c => samePath(c.path, t.path))),
      rebaselined: [...s.rebaselined.filter(r => !taken.some(c => samePath(c.path, r.path))), ...taken.map(c => ({ path: c.path, by: 'you', at: now }))].slice(-EVIDENCE_LIMITS.files),
      changes,
      status: statusOf(changes),
      checkedAt: now,
    }
  })
  return isChanged ? { ...store, snapshots } : store
}

// ---------------------------------------------------------------------------
// Words

const fileName = (path: string): string => path.replace(/\\/g, '/').split('/').filter(Boolean).pop() ?? path

const names = (paths: readonly string[]): string => {
  const unique = [...new Set(paths.map(fileName))]
  return unique.length <= 2 ? unique.join(', ') : `${unique.slice(0, 2).join(', ')} +${unique.length - 2}`
}

/** The checks to run again, by name ("Tests, Type-check"); a milestone verified with none says so. */
export function rerunWords(s: Snapshot): string {
  return s.checks.length === 0 ? 'no check was recorded: review it' : `rerun ${[...new Set(s.checks.map(c => c.label))].join(', ')}`
}

/** A stale snapshot whose changed files are all documentation: its checks do not cover them, so a review does. */
const isDocsOnly = (s: Snapshot, changes: readonly EvidenceChange[]): boolean => changes.length > 0 && changes.every(c => s.files.find(f => samePath(f.path, c.path))?.isDoc === true)

/** What the snapshot says now, in a line for a milestone's row (null while it is current and nothing was re-verified). */
export function evidenceLine(s: Snapshot): string | null {
  if (s.status === 'stale') {
    const stale = s.changes.filter(c => !c.isByActive)
    const what = stale.some(c => c.kind === 'deleted') && stale.every(c => c.kind === 'deleted') ? 'deleted' : 'changed'
    return `${names(stale.map(c => c.path))} ${what} since ${clock(s.verifiedAt)} · ${isDocsOnly(s, stale) ? 'review the change' : rerunWords(s)}`
  }
  if (s.status === 'changing') {
    const by = [...new Set(s.changes.map(c => c.by).filter((b): b is string => b !== null))]
    return `${names(s.changes.map(c => c.path))} being changed by ${by.join(', ') || 'the work under way'}`
  }
  if (s.rebaselined.length > 0) return `re-verified by ${[...new Set(s.rebaselined.map(r => r.by))].join(', ')}`
  return null
}

/** Who changed a stale file, in words: the later milestone, no milestone under way, or outside Sentinel's view. */
const byWords = (c: EvidenceChange): string => (c.by !== null ? `by "${c.by}"` : c.isSeen ? 'with no milestone under way' : "outside Claude's tools")

/**
 * For Claude (the fresh context's block, the handoff prompt): the milestones whose verification is stale,
 * what changed and what to run again. Null with none.
 */
export function staleText(snapshots: readonly Snapshot[]): string | null {
  const stale = snapshots.filter(s => s.status === 'stale').slice(-5)
  if (stale.length === 0) return null
  const items = stale.map(s => {
    const changes = s.changes.filter(c => !c.isByActive)
    const what = changes.map(c => `${fileName(c.path)} ${c.kind} ${byWords(c)}`).slice(0, 4).join(', ')
    const rerun = s.checks.length === 0 || isDocsOnly(s, changes) ? 'no check covers that, so review it' : `rerun ${[...new Set(s.checks.map(c => `${c.label} (${c.command})`))].join(', ')}`
    return `"${s.subject}" (verified ${clock(s.verifiedAt)}): ${what}; ${rerun}`
  })
  return `Verification gone stale since it was recorded (files changed after the milestone was verified; this does not mean it is wrong): ${items.join('; ')}. Rerun those checks before relying on these milestones, and record the result.`
}

// ---------------------------------------------------------------------------
// Stored

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const num = (v: unknown): number | null => (typeof v === 'number' && Number.isFinite(v) ? v : null)
const str = (v: unknown, max = 400): string => (typeof v === 'string' ? v.slice(0, max) : '')

function fileOf(raw: unknown): EvidenceFile | null {
  if (!isRecord(raw) || typeof raw.path !== 'string' || raw.path === '') return null
  return { path: str(raw.path), exists: raw.exists !== false, ...(raw.isDir === true ? { isDir: true } : {}), ...(raw.isDoc === true ? { isDoc: true } : {}), size: num(raw.size), mtimeMs: num(raw.mtimeMs), blob: typeof raw.blob === 'string' && /^[0-9a-f]{40,64}$/.test(raw.blob) ? raw.blob : null }
}

function changeOf(raw: unknown): EvidenceChange | null {
  if (!isRecord(raw) || typeof raw.path !== 'string') return null
  const kind = raw.kind === 'deleted' || raw.kind === 'created' ? raw.kind : 'changed'
  const f = isRecord(raw.found) ? raw.found : {}
  return {
    path: str(raw.path),
    kind,
    by: typeof raw.by === 'string' ? str(raw.by, 120) : null,
    byKey: typeof raw.byKey === 'string' ? str(raw.byKey, 120) : null,
    isByActive: raw.isByActive === true,
    isSeen: raw.isSeen === true,
    at: num(raw.at),
    foundAt: num(raw.foundAt) ?? 0,
    found: { size: num(f.size), mtimeMs: num(f.mtimeMs), blob: typeof f.blob === 'string' && /^[0-9a-f]{40,64}$/.test(f.blob) ? f.blob : null },
  }
}

function snapshotOf(raw: unknown): Snapshot | null {
  if (!isRecord(raw) || typeof raw.key !== 'string' || typeof raw.subject !== 'string' || num(raw.verifiedAt) === null) return null
  const list = <T>(v: unknown, of: (x: unknown) => T | null, max: number): T[] => (Array.isArray(v) ? v.map(of).filter((x): x is T => x !== null).slice(-max) : [])
  const checks = list(raw.checks, c => (isRecord(c) && typeof c.kind === 'string' && num(c.at) !== null ? { kind: str(c.kind, 40), label: str(c.label, 40) || str(c.kind, 40), command: str(c.command, 160), at: num(c.at) ?? 0 } : null), EVIDENCE_LIMITS.checks)
  const touches = list(raw.touches, t => (isRecord(t) && typeof t.path === 'string' && num(t.at) !== null ? { path: str(t.path), key: typeof t.key === 'string' ? str(t.key, 120) : null, subject: typeof t.subject === 'string' ? str(t.subject, 120) : null, at: num(t.at) ?? 0 } : null), EVIDENCE_LIMITS.touches)
  const rebaselined = list(raw.rebaselined, r => (isRecord(r) && typeof r.path === 'string' && typeof r.by === 'string' ? { path: str(r.path), by: str(r.by, 120), at: num(r.at) ?? 0 } : null), EVIDENCE_LIMITS.files)
  const changes = list(raw.changes, changeOf, EVIDENCE_LIMITS.files)
  return {
    key: str(raw.key, 120),
    subject: str(raw.subject, 120),
    verifiedAt: num(raw.verifiedAt) ?? 0,
    session: num(raw.session) ?? 1,
    checks,
    files: list(raw.files, fileOf, EVIDENCE_LIMITS.files),
    head: typeof raw.head === 'string' && /^[0-9a-f]{7,64}$/.test(raw.head) ? raw.head : null,
    touches,
    rebaselined,
    status: raw.status === 'stale' || raw.status === 'changing' ? raw.status : changes.length > 0 ? statusOf(changes) : 'current',
    changes,
    checkedAt: num(raw.checkedAt),
  }
}

/** A stored evidence store, validated: anything malformed reads as none. */
export function evidenceOf(raw: unknown): EvidenceStore {
  if (!isRecord(raw)) return emptyEvidence()
  const work: Record<string, MilestoneWork> = {}
  if (isRecord(raw.work)) {
    for (const [key, w] of Object.entries(raw.work).slice(-EVIDENCE_LIMITS.snapshots)) {
      if (!isRecord(w) || num(w.since) === null) continue
      const files = Array.isArray(w.files) ? w.files.filter(isRecord).filter(f => typeof f.path === 'string' && num(f.at) !== null).map(f => ({ path: str(f.path), at: num(f.at) ?? 0 })).slice(-EVIDENCE_LIMITS.files) : []
      const outputs = Array.isArray(w.outputs) ? w.outputs.filter((o): o is string => typeof o === 'string').map(o => o.slice(0, 400)).slice(-EVIDENCE_LIMITS.outputs) : []
      work[key.slice(0, 120)] = { since: num(w.since) ?? 0, files, outputs }
    }
  }
  const snapshots = Array.isArray(raw.snapshots) ? raw.snapshots.map(snapshotOf).filter((s): s is Snapshot => s !== null).slice(-EVIDENCE_LIMITS.snapshots) : []
  return { work, snapshots }
}

