/**
 * The plan's five-hour usage window, as Claude Code reports it.
 *
 * On a claude.ai plan each API response carries the account's rate-limit windows, and Claude Code
 * hands them on: `$.session.usage().rateLimits`, and `session.measure`'s `rateLimits` (its `changed`
 * names 'rateLimits' when a window moves a whole point, appears or leaves). Each window has a
 * `kind` ('five_hour', 'seven_day', a Claude gateway's 'spend_limit'), `percentUsed` (0 to 100, at
 * most one decimal) and `resetsAt` (ISO 8601). Seen live on Claude Code 2.1.296: the list is empty
 * before the first response of a session, then reads five_hour 47% (resets 04:20Z) and seven_day
 * 17%; it carries across /clear; off a subscription (an API key) it stays empty.
 *
 * Nothing here estimates. The percentage is the engine's latest reading and the countdown is the
 * window's own reset time against the clock. Once that time has passed, the old reading says
 * nothing about the new window: it reads "reset" with no number until a response brings the new
 * window's figure (a window that drops out of the list at its reset reads the same). A request
 * Claude Code ended on the rate limit (StopFailure `rate_limit`), or a window read at 100%, reads
 * "limit reached" until a turn is answered again, a reading under 100% comes, or the window resets.
 *
 * Pure: the Runtime feeds it readings and draws its view.
 */

/** One window as Claude Code reads it (SessionRateLimit, Claude Code 2.1.289 and later). */
export type RateLimitReading = { kind: string; percentUsed: number; resetsAt?: string }

/** A window's latest reading: how much is used, when it resets (ms; null when the engine gave no time), when it was read. */
export type WindowReading = { percent: number; resetsAt: number | null; readAt: number }

export type LimitWindow = 'five_hour' | 'seven_day'

export type PlanUsage = {
  fiveHour: WindowReading | null
  sevenDay: WindowReading | null
  /**
   * A turn was answered and the list still held no five-hour window: an API key, or a plan
   * without one. False until then (the list is empty before the first response too).
   */
  isAbsent: boolean
  /** Claude Code ended a request on the rate limit: when, and the window read as full then (null: none was). */
  limited: { at: number; window: LimitWindow | null } | null
}

export const emptyPlanUsage = (): PlanUsage => ({ fiveHour: null, sevenDay: null, isAbsent: false, limited: null })

/** From this share of the window used, the reading asks for a look (amber); at 100% the limit is reached (red). */
export const WARN_PERCENT = 80

const percentOf = (n: number): number => (Number.isFinite(n) ? Math.max(0, Math.round(n * 10) / 10) : 0)

function timeOf(iso: string | undefined): number | null {
  if (iso === undefined) return null
  const at = Date.parse(iso)
  return Number.isFinite(at) ? at : null
}

const readingOf = (r: RateLimitReading | undefined, now: number): WindowReading | null =>
  r === undefined ? null : { percent: percentOf(r.percentUsed), resetsAt: timeOf(r.resetsAt), readAt: now }

/** Two readings that say the same (a refresh of an unchanged window): the state is kept as it is. */
const isSame = (a: WindowReading | null, b: WindowReading | null): boolean =>
  a === b || (a !== null && b !== null && a.percent === b.percent && a.resetsAt === b.resetsAt)

/**
 * The windows Claude Code reports now. A window missing from the list keeps its last reading (it
 * lapses at its own reset time, in the view). `isAfterAnswer`: read right after a turn was answered,
 * so an API response has come back and an empty list means no five-hour window on this account.
 */
export function readWindows(state: PlanUsage, rateLimits: readonly RateLimitReading[], now: number, isAfterAnswer = false): PlanUsage {
  const five = readingOf(rateLimits.find(r => r.kind === 'five_hour'), now)
  const seven = readingOf(rateLimits.find(r => r.kind === 'seven_day'), now)
  const fiveHour = five === null ? state.fiveHour : isSame(state.fiveHour, five) ? state.fiveHour : five
  const sevenDay = seven === null ? state.sevenDay : isSame(state.sevenDay, seven) ? state.sevenDay : seven
  const isAbsent = five !== null ? false : isAfterAnswer && state.fiveHour === null ? true : state.isAbsent
  // A fresh reading under 100% of the window that was full: the limit has lifted.
  let limited = state.limited
  if (limited !== null && limited.window !== null) {
    const fresh = limited.window === 'five_hour' ? five : seven
    if (fresh !== null && fresh.percent < 100 && now > limited.at) limited = null
  }
  if (fiveHour === state.fiveHour && sevenDay === state.sevenDay && isAbsent === state.isAbsent && limited === state.limited) return state
  return { fiveHour, sevenDay, isAbsent, limited }
}

/** Claude Code ended a request on the rate limit (StopFailure `rate_limit`). */
export function noteRateLimited(state: PlanUsage, now: number): PlanUsage {
  const window: LimitWindow | null = (state.fiveHour?.percent ?? 0) >= 100 ? 'five_hour' : (state.sevenDay?.percent ?? 0) >= 100 ? 'seven_day' : null
  return { ...state, limited: { at: now, window } }
}

/** A turn of the main conversation was answered: whatever limit stopped a request before has lifted. */
export function noteAnswered(state: PlanUsage): PlanUsage {
  return state.limited === null ? state : { ...state, limited: null }
}

export type PlanUsageView =
  /** No reading yet: before the session's first API response. */
  | { kind: 'pending' }
  /** Responses came back with no five-hour window: an API key, or a plan without one. */
  | { kind: 'absent' }
  | { kind: 'reading'; percent: number; resetsAt: number | null; leftMs: number | null; isHigh: boolean }
  /** The window's reset time has passed: a new window, with no reading of it until the next response. */
  | { kind: 'reset'; at: number }
  /** The limit is reached: a request was refused for it, or the window reads 100%. */
  | { kind: 'limited'; window: LimitWindow | null; percent: number | null; resetsAt: number | null; leftMs: number | null }

const isPast = (w: WindowReading | null, now: number): boolean => w !== null && w.resetsAt !== null && now >= w.resetsAt

const leftOf = (w: WindowReading | null, now: number): number | null => (w === null || w.resetsAt === null ? null : Math.max(0, w.resetsAt - now))

/** The five-hour window at `now` (system time: `resetsAt` is wall-clock). */
export function planUsageView(state: PlanUsage, now: number): PlanUsageView {
  const five = state.fiveHour
  const limited = state.limited
  if (limited !== null) {
    const full = limited.window === 'seven_day' ? state.sevenDay : limited.window === 'five_hour' ? five : null
    // A known full window that has since reset no longer holds the limit; an unknown one holds until a turn is answered.
    if (!isPast(full, now)) {
      const shown = limited.window === 'seven_day' ? state.sevenDay : isPast(five, now) ? null : five
      return { kind: 'limited', window: limited.window, percent: shown?.percent ?? null, resetsAt: full?.resetsAt ?? null, leftMs: leftOf(full, now) }
    }
  }
  if (five === null) return state.isAbsent ? { kind: 'absent' } : { kind: 'pending' }
  if (isPast(five, now)) return { kind: 'reset', at: five.resetsAt ?? now }
  if (five.percent >= 100) return { kind: 'limited', window: 'five_hour', percent: five.percent, resetsAt: five.resetsAt, leftMs: leftOf(five, now) }
  return { kind: 'reading', percent: five.percent, resetsAt: five.resetsAt, leftMs: leftOf(five, now), isHigh: five.percent >= WARN_PERCENT }
}

/** Whether a countdown or a reset is still ahead, so a minute tick has something to redraw. */
export const isTicking = (state: PlanUsage, now: number): boolean => {
  const v = planUsageView(state, now)
  return v.kind === 'reading' || (v.kind === 'limited' && v.leftMs !== null)
}

/** One window for the detail views (Context → Run): its name, its reading, its reset. */
export type WindowRow = { key: LimitWindow; name: string; percent: number | null; resetsAt: number | null; leftMs: number | null; isReset: boolean }

export function windowRows(state: PlanUsage, now: number): WindowRow[] {
  const rows: WindowRow[] = []
  const add = (key: LimitWindow, name: string, w: WindowReading | null) => {
    if (w === null) return
    const isReset = isPast(w, now)
    rows.push({ key, name, percent: isReset ? null : w.percent, resetsAt: w.resetsAt, leftMs: isReset ? null : leftOf(w, now), isReset })
  }
  add('five_hour', '5-hour', state.fiveHour)
  add('seven_day', '7-day', state.sevenDay)
  return rows
}

files.hooks/features/quest.ts:
/**
 * Quest log: a light game layer over verified progress, shown while the
 * person chose the Quest log answer style.
 *
 * XP is awarded only for outcomes Control Room counts itself: a milestone
 * Claude marked done, a check that passes (or passes again after failing), a
 * plan finished, a handoff whose notes were verified. Never for activity
 * (lines written, files touched, tool calls), which would reward churn, and
 * never for anything Claude merely says. Each outcome pays once: a milestone
 * once per run, a check's first pass once per turn. Pure: the runtime decides
 * when an event happened.
 */

import { clean } from '../core/text'

export type QuestEventKind = 'milestone' | 'green' | 'comeback' | 'fullClear' | 'handoff'

export const XP: Record<QuestEventKind, number> = { milestone: 50, green: 10, comeback: 30, fullClear: 100, handoff: 40 }

export type AchievementId = 'first-green' | 'comeback' | 'full-clear' | 'clean-handoff' | 'relay' | 'long-haul'

export const ACHIEVEMENTS: readonly { id: AchievementId; name: string; hint: string }[] = [
  { id: 'first-green', name: 'First green', hint: 'A check passes' },
  { id: 'comeback', name: 'Comeback', hint: 'A failing check passes again' },
  { id: 'full-clear', name: 'Full clear', hint: 'Every milestone of a plan of three or more' },
  { id: 'clean-handoff', name: 'Clean handoff', hint: 'Autopilot hands off with verified notes' },
  { id: 'relay', name: 'Relay', hint: 'One run across three contexts' },
  { id: 'long-haul', name: 'Long haul', hint: 'Ten milestones done in one run' },
]

/** What an event unlocks the first time: a comeback is a check passing too. */
const UNLOCKED_BY: Partial<Record<QuestEventKind, readonly AchievementId[]>> = {
  green: ['first-green'],
  comeback: ['comeback', 'first-green'],
  fullClear: ['full-clear'],
  handoff: ['clean-handoff'],
}

export type QuestAward = { at: number; xp: number; text: string }

/** Lifetime progress, kept in the plugin store. */
export type QuestState = { v: 1; xp: number; unlocked: Partial<Record<AchievementId, number>>; recent: QuestAward[] }

/** A run's share: its XP, and the milestones already paid for (by their key). */
export type RunQuest = { xp: number; paid: string[] }

export const emptyQuest = (): QuestState => ({ v: 1, xp: 0, unlocked: {}, recent: [] })

export const emptyRunQuest = (): RunQuest => ({ xp: 0, paid: [] })

/** Level n starts at 50·n·(n−1) XP: 0, 100, 300, 600, 1000, 1500 … */
export function levelOf(xp: number): { level: number; floor: number; next: number } {
  const x = Math.max(0, Math.floor(xp))
  let level = 1
  while (50 * (level + 1) * level <= x) level += 1
  return { level, floor: 50 * level * (level - 1), next: 50 * (level + 1) * level }
}

export type Award = { state: QuestState; xp: number; levelUp: number | null; unlocked: AchievementId[] }

/** One event: its XP, its line in the log, and the achievement it unlocks the first time. */
export function award(state: QuestState, event: { kind: QuestEventKind; text: string }, now: number): Award {
  const xp = XP[event.kind]
  const before = levelOf(state.xp).level
  const unlocked: AchievementId[] = []
  const next: QuestState = {
    v: 1,
    xp: state.xp + xp,
    unlocked: { ...state.unlocked },
    recent: [{ at: now, xp, text: clean(event.text, 90) }, ...state.recent].slice(0, RECENT_MAX),
  }
  for (const id of UNLOCKED_BY[event.kind] ?? []) {
    if (next.unlocked[id] !== undefined) continue
    next.unlocked[id] = now
    unlocked.push(id)
  }
  const after = levelOf(next.xp).level
  return { state: next, xp, levelUp: after > before ? after : null, unlocked }
}

/** Achievements a run earns by its shape: three contexts, ten milestones. No XP. */
export function unlockForRun(state: QuestState, run: { sessions: number; milestonesDone: number }, now: number): { state: QuestState; unlocked: AchievementId[] } {
  const unlocked: AchievementId[] = []
  const add = (id: AchievementId, isEarned: boolean) => {
    if (isEarned && state.unlocked[id] === undefined && !unlocked.includes(id)) unlocked.push(id)
  }
  add('relay', run.sessions >= 3)
  add('long-haul', run.milestonesDone >= 10)
  if (unlocked.length === 0) return { state, unlocked }
  const next = { ...state, unlocked: { ...state.unlocked } }
  for (const id of unlocked) next.unlocked[id] = now
  return { state: next, unlocked }
}

export const achievementName = (id: AchievementId): string => ACHIEVEMENTS.find(a => a.id === id)?.name ?? id

const RECENT_MAX = 8

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

const count = (v: unknown): number => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? Math.floor(v) : 0)

/** A stored quest, validated: anything malformed starts over at zero. */
export function questOf(raw: unknown): QuestState {
  if (!isRecord(raw)) return emptyQuest()
  const unlocked: Partial<Record<AchievementId, number>> = {}
  if (isRecord(raw.unlocked)) {
    for (const a of ACHIEVEMENTS) {
      const at = raw.unlocked[a.id]
      if (typeof at === 'number' && Number.isFinite(at)) unlocked[a.id] = at
    }
  }
  const recent = Array.isArray(raw.recent)
    ? raw.recent
        .filter(isRecord)
        .map(r => ({ at: count(r.at), xp: count(r.xp), text: typeof r.text === 'string' ? clean(r.text, 90) : '' }))
        .filter(r => r.text !== '')
        .slice(0, RECENT_MAX)
    : []
  return { v: 1, xp: count(raw.xp), unlocked, recent }
}

/** A run's stored quest share, validated. */
export function runQuestOf(raw: unknown): RunQuest {
  if (!isRecord(raw)) return emptyRunQuest()
  const paid = Array.isArray(raw.paid) ? raw.paid.filter((x): x is string => typeof x === 'string').slice(-200) : []
  return { xp: count(raw.xp), paid }
}

files.hooks/features/digest.ts:
/**
 * Signal from the raw activity: what needs a look (Attention), what the
 * changed files are (grouped, with generated and temporary files apart),
 * what Claude did this turn in a few words, and what it is doing right now.
 *
 * Pure functions over the tracker's records. Nothing here calls a model:
 * every line is counted or read from a tool's own result, so it is cheap and
 * never invented. Where a fact is not knowable (a background command's
 * outcome), the views say so instead of guessing.
 */

import { plural } from '../core/format'
import { relativeTo } from '../core/text'
import type { ActivityItem, ActivityKind, FileChange } from './activity'
import type { Progress } from './plan'
import { VALIDATION_DOING, VALIDATION_LABEL, type ValidationSummary } from './validation'

// ---------------------------------------------------------------------------
// Changed files, grouped

export type ChangeGroup = 'code' | 'tests' | 'docs' | 'config' | 'other' | 'generated'

export const GROUP_LABEL: Record<ChangeGroup, string> = {
  code: 'Code',
  tests: 'Tests',
  docs: 'Docs',
  config: 'Config',
  other: 'Other',
  generated: 'Generated and temporary',
}

/** Real project changes first, in this order; generated and temporary files last and apart. */
export const GROUP_ORDER: readonly ChangeGroup[] = ['code', 'tests', 'docs', 'config', 'other', 'generated']

const TEMP_DIR = /(^|\/)(tmp|temp|\.tmp|scratch|scratchpad|\.cache|node_modules|__pycache__|\.pytest_cache|\.venv|venv|dist|target|coverage|\.next|\.nuxt|\.turbo|bin\/(debug|release)|obj)\//i
const SYSTEM_TEMP = /(^|\/)(appdata\/local\/temp|private\/var\/folders|var\/folders|tmp)\//i
const TEST_FILE = /(^|\/)(tests?|__tests__|specs?|e2e|cypress)\/|[._-](test|spec)\.[a-z0-9]+$|(^|\/)test_[^/]+\.py$|_test\.(go|py|rb|exs?)$/i
/** `LordshipTests.cs`, `ParserTest.java`: case matters, so `Contest.cs` is not a test. */
const TEST_CLASS = /[a-z0-9]Tests?\.(cs|java|kt|kts|swift|scala|groovy)$/
const DOC_FILE = /\.(md|mdx|markdown|rst|adoc|txt)$|(^|\/)(docs?|documentation)\//i
const CONFIG_FILE =
  /(^|\/)(\.github|\.vscode|\.devcontainer)\/|(^|\/)(package(-lock)?\.json|pnpm-lock\.yaml|yarn\.lock|tsconfig[^/]*\.json|jsconfig\.json|\.?eslintrc[^/]*|\.prettierrc[^/]*|\.editorconfig|\.gitignore|\.gitattributes|\.npmrc|\.env\.example|dockerfile|docker-compose[^/]*|makefile|cmakelists\.txt|cargo\.(toml|lock)|go\.(mod|sum)|pyproject\.toml|setup\.(cfg|py)|requirements[^/]*\.txt|gemfile(\.lock)?|[^/]*\.(csproj|sln|props|targets|gradle(\.kts)?)|[^/]*\.config\.(js|cjs|mjs|ts))$|\.(ya?ml|toml|ini|cfg|conf|plist)$/i
const CODE_FILE =
  /\.(ts|tsx|js|jsx|mjs|cjs|py|rb|go|rs|java|kt|kts|swift|c|cc|cpp|h|hpp|cs|fs|php|scala|clj|ex|exs|erl|hs|lua|dart|vue|svelte|astro|sql|sh|bash|zsh|ps1|psm1|r|jl|zig|nim|ml|m|mm|css|scss|less|html|htm|xml|json|graphql|proto|shader|hlsl|glsl|ipynb)$/i

/**
 * Which group a changed file belongs to. Generated and temporary: outside
 * the project, in a temp, cache or build folder, Claude Code's own `.claude`
 * folder, or the handoff notes Context Autopilot asks for.
 */
export function groupOf(path: string, ctx: { root: string; handoffFile: string }): ChangeGroup {
  const abs = path.replace(/\\/g, '/')
  const root = ctx.root.replace(/\\/g, '/').replace(/\/+$/, '')
  const isInside = root !== '' && (abs.toLowerCase() === root.toLowerCase() || abs.toLowerCase().startsWith(`${root.toLowerCase()}/`))
  const rel = isInside ? relativeTo(abs, root) : abs
  const handoff = ctx.handoffFile.replace(/\\/g, '/').replace(/^\.\//, '')
  if (root !== '' && !isInside && /^([a-z]:)?\//i.test(abs)) return 'generated'
  if (SYSTEM_TEMP.test(abs) || TEMP_DIR.test(`/${rel}`) || /(^|\/)\.claude\//i.test(`/${rel}`)) return 'generated'
  if (rel.toLowerCase() === handoff.toLowerCase()) return 'generated'
  if (TEST_FILE.test(rel) || TEST_CLASS.test(rel)) return 'tests'
  if (CONFIG_FILE.test(rel)) return 'config'
  if (DOC_FILE.test(rel)) return 'docs'
  if (CODE_FILE.test(rel)) return 'code'
  return 'other'
}

// ---------------------------------------------------------------------------
// Attention

export type AttentionKind = 'failed' | 'blocked' | 'held' | 'running' | 'slow'

export type Attention = {
  id: string
  kind: AttentionKind
  tool: string
  title: string
  reason: string | null
  /** Failed calls: whether a later attempt of the same thing succeeded. */
  state: 'unresolved' | 'recovered' | null
  attempts: number
  durationMs: number | null
  since: number
  at: number
}

/** A long-running call is worth a look after this; a check or a build takes longer as a rule. */
const RUNNING_AFTER_MS = 20_000
const SLOW_MS: Record<'tool' | 'shell' | 'check', number> = { tool: 45_000, shell: 120_000, check: 600_000 }

/** What a retry of a call would look like: the same tool on the same thing. */
const signatureOf = (i: ActivityItem): string => `${i.kind === 'edit' ? 'edit' : i.tool}\u0000${i.label}`

const slowLimitOf = (i: ActivityItem): number => (i.validation !== null ? SLOW_MS.check : i.kind === 'shell' ? SLOW_MS.shell : SLOW_MS.tool)

/**
 * The calls that need a look, in this order: failures nothing has fixed,
 * refusals, calls held back by the Resource Governor, long-running calls,
 * unusually slow ones, then failures a later attempt recovered from.
 * `items` are the main conversation's calls of one turn, oldest first.
 */
export function attentionOf(items: readonly ActivityItem[], now: number): Attention[] {
  const out: Attention[] = []
  const failures = new Map<string, Attention>()
  for (const i of items) {
    const sig = signatureOf(i)
    const open = failures.get(sig)
    if (i.status === 'ok' && open !== undefined) {
      open.state = 'recovered'
      failures.delete(sig)
    }
    if (i.status === 'error') {
      if (open !== undefined) {
        open.attempts += 1
        open.reason = i.reason ?? open.reason
        open.at = i.endedAt ?? i.startedAt
        continue
      }
      const entry: Attention = { id: i.id, kind: 'failed', tool: i.tool, title: i.label || i.tool, reason: i.reason, state: 'unresolved', attempts: 1, durationMs: null, since: i.startedAt, at: i.endedAt ?? i.startedAt }
      failures.set(sig, entry)
      out.push(entry)
      continue
    }
    if (i.status === 'denied' || i.status === 'held') {
      out.push({ id: i.id, kind: i.status === 'held' ? 'held' : 'blocked', tool: i.tool, title: i.label || i.tool, reason: i.reason, state: null, attempts: 1, durationMs: null, since: i.startedAt, at: i.startedAt })
      continue
    }
    const duration = (i.endedAt ?? now) - i.startedAt
    if (i.status === 'running' && duration >= RUNNING_AFTER_MS) {
      out.push({ id: i.id, kind: 'running', tool: i.tool, title: i.label || i.tool, reason: null, state: null, attempts: 1, durationMs: null, since: i.startedAt, at: i.startedAt })
    } else if (i.status === 'ok' && i.backgroundTaskId === null && duration >= slowLimitOf(i)) {
      out.push({ id: i.id, kind: 'slow', tool: i.tool, title: i.label || i.tool, reason: null, state: null, attempts: 1, durationMs: duration, since: i.startedAt, at: i.startedAt })
    }
  }
  const rank = (a: Attention): number =>
    a.kind === 'failed' ? (a.state === 'unresolved' ? 0 : 5) : a.kind === 'blocked' ? 1 : a.kind === 'held' ? 2 : a.kind === 'running' ? 3 : 4
  return out.sort((a, b) => rank(a) - rank(b) || b.at - a.at)
}

/** Attention that is still open: an unresolved failure, a refusal, a held call. */
export const isOpen = (a: Attention): boolean => (a.kind === 'failed' && a.state === 'unresolved') || a.kind === 'blocked' || a.kind === 'held'

// ---------------------------------------------------------------------------
// What Claude did this turn

const KIND_WORD: Partial<Record<ActivityKind, [string, string]>> = {
  search: ['search', 'searches'],
  web: ['web lookup', 'web lookups'],
  agent: ['subagent', 'subagents'],
  mcp: ['connector call', 'connector calls'],
}

const times = (n: number): string => (n === 1 ? 'once' : n === 2 ? 'twice' : `${n}×`)

/**
 * A few plain lines on the turn, from counts alone: what changed, which
 * checks ran and how they ended, how much was read, what went wrong and
 * whether it was fixed, and the milestones finished.
 */
export function turnSummaryOf(input: {
  items: readonly ActivityItem[]
  changed: readonly FileChange[]
  groupOf: (path: string) => ChangeGroup
  validation: readonly ValidationSummary[]
  attention: readonly Attention[]
  milestonesDone: number
}): string[] {
  const lines: string[] = []
  const real = input.changed.filter(c => input.groupOf(c.path) !== 'generated')
  if (real.length > 0) {
    const counts = new Map<ChangeGroup, number>()
    for (const c of real) counts.set(input.groupOf(c.path), (counts.get(input.groupOf(c.path)) ?? 0) + 1)
    const parts = GROUP_ORDER.filter(g => counts.has(g)).map(g => `${counts.get(g)} in ${GROUP_LABEL[g].toLowerCase()}`)
    lines.push(`Changed ${plural(real.length, 'file')}${counts.size > 1 ? ` · ${parts.join(', ')}` : ''}`)
  }
  const checks: string[] = []
  for (const v of input.validation) {
    const ran = input.items.filter(i => i.validation === v.kind).length
    if (ran === 0) continue
    const outcome =
      v.status === 'running' ? 'running now' : v.status === 'failed' ? 'failing' : v.status === 'passed' ? (v.isRecovered ? 'passing after a fix' : 'passing') : v.status === 'background' ? 'in the background' : v.status
    checks.push(`${VALIDATION_LABEL[v.kind].toLowerCase()} ${times(ran)}, ${outcome}`)
  }
  if (checks.length > 0) lines.push(`Ran ${checks.join(' · ')}`)
  const reads = new Set(input.items.filter(i => i.kind === 'read' && i.status === 'ok').map(i => i.label)).size
  const looked: string[] = reads > 0 ? [`Read ${plural(reads, 'file')}`] : []
  for (const [kind, [one, many]] of Object.entries(KIND_WORD) as [ActivityKind, [string, string]][]) {
    const n = input.items.filter(i => i.kind === kind).length
    if (n > 0) looked.push(`${n} ${n === 1 ? one : many}`)
  }
  if (looked.length > 0) lines.push(looked.join(' · '))
  const failed = input.attention.filter(a => a.kind === 'failed')
  const fixed = failed.filter(a => a.state === 'recovered').length
  const open = failed.length - fixed
  const refused = input.attention.filter(a => a.kind === 'blocked' || a.kind === 'held').length
  const trouble: string[] = []
  if (fixed > 0) trouble.push(`${plural(fixed, 'failure')} recovered`)
  if (open > 0) trouble.push(`${open} still failing`)
  if (refused > 0) trouble.push(`${refused} blocked`)
  if (trouble.length > 0) lines.push(trouble.join(' · '))
  if (input.milestonesDone > 0) lines.push(`Finished ${plural(input.milestonesDone, 'milestone')}`)
  return lines
}

// ---------------------------------------------------------------------------
// What Claude is doing right now

const fileOf = (label: string): string => label.split('/').pop() ?? label

const RANK: Partial<Record<ActivityKind, number>> = { shell: 0, agent: 1, web: 2, edit: 3, mcp: 4, read: 5, search: 6, task: 7 }

/** Commands that only set up where or how the next one runs: `cd app && npm run build` is a build, not a cd. */
const SETUP_PROGRAM = /^(cd|chdir|pushd|set-location|sl|export|set|source|\.)$/i
/** An environment setting ahead of a command: `NODE_ENV=production node …`, PowerShell's `$env:DEBUG='1'`. */
const ASSIGNMENT = /^(\$env:)?[A-Za-z_]\w*=/i

const programOf = (word: string): string => word.replace(/^["']|["']$/g, '').split(/[\\/]/).pop() ?? word

/** The words of the command a shell line runs for its work: past a change of directory or an environment setting. */
function workWords(line: string): string[] {
  let first: string[] | null = null
  for (const part of line.split(/&&|\|\||;/)) {
    const words = part.trim().split(/\s+/).filter(w => w !== '')
    while (words.length > 1 && ASSIGNMENT.test(words[0] ?? '')) words.shift()
    if (words.length === 0 || ASSIGNMENT.test(words[0] ?? '')) continue
    first ??= words
    if (!SETUP_PROGRAM.test(programOf(words[0] ?? ''))) return words
  }
  return first ?? []
}

/** A running call in a few words: "Running tests", "Editing renderer.ts", "Searching the code". */
export function doingOf(i: ActivityItem): string {
  if (i.validation !== null) return VALIDATION_DOING[i.validation]
  switch (i.kind) {
    case 'shell': {
      const words = workWords(i.label)
      const program = programOf(words[0] ?? '')
      if (i.heavy.includes('install')) return 'Installing packages'
      if (/^git$/i.test(program)) return `Running git ${words[1] ?? ''}`.trim()
      return program === '' ? 'Running a command' : `Running ${program}`
    }
    case 'edit':
      return `Editing ${fileOf(i.label)}`
    case 'read':
      return `Reading ${fileOf(i.label)}`
    case 'search':
      return 'Searching the code'
    case 'web':
      return 'Looking things up'
    case 'agent':
      return i.label === '' ? 'Running a subagent' : `Subagent: ${i.label}`
    case 'task':
      return 'Updating the plan'
    case 'mcp':
      return `Using ${i.label.split(' · ')[0] ?? 'a connector'}`
    default:
      return `Using ${i.tool}`
  }
}

/**
 * The work line: the milestone in progress in Claude's own words when it
 * named one; else what the running call is doing; else, mid-turn, that it is
 * thinking. Null between turns.
 */
export function nowOf(input: { isTurnRunning: boolean; running: readonly ActivityItem[]; progress: Progress }): { text: string; source: 'plan' | 'tool' | 'thinking' } | null {
  if (!input.isTurnRunning) return null
  const current = input.progress.current
  const check = input.running.find(i => i.validation !== null && i.agentId === null)
  // A check running now says more than the milestone it serves.
  if (check !== undefined) return { text: doingOf(check), source: 'tool' }
  if (current !== null) return { text: current.activeForm ?? current.subject, source: 'plan' }
  const main = [...input.running].filter(i => i.agentId === null).sort((a, b) => (RANK[a.kind] ?? 9) - (RANK[b.kind] ?? 9) || a.startedAt - b.startedAt)[0]
  if (main !== undefined) return { text: doingOf(main), source: 'tool' }
  return { text: 'Thinking', source: 'thinking' }
}

